/// accessible for moderation purposes and provide a complete audit trail of
/// discussion evolution over time.
///
/// @namespace Comments
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model economic_discussion_comment_versions {
  //----
  // COLUMNS
  //----
