  id String @id @db.Uuid

  /// Original comment this version belongs to. {@link
  /// economic_discussion_comments.id}
  economic_discussion_comment_id String @db.Uuid

  /// Comment content at the time of snapshot.
  content String

  /// Snapshot creation timestamp when version was saved.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  // spellchecker: ignore-next-line
  comment economic_discussion_comments @relation(fields: [economic_discussion_comment_id], references: [id], onDelete: Cascade, map: "economic_discussion_comment_versions_economic_discussi_8dbe27f3")

  // spellchecker: ignore-next-line
  @@index([economic_discussion_comment_id, created_at], map: "economic_discussion_comment_versions_economic_discussi_2b24b981")
}

