import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEconomicDiscussionMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionMember";
import type { IEconomicDiscussionMemberSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionMemberSession";

/**
 * Test updating a member session when their IP address changes during active
 * session. This validates security tracking when users switch networks (e.g.,
 * moving from WiFi to mobile data). Verifies that the session IP field is
 * properly updated while maintaining session integrity and authentication
 * status.
 */
export async function test_api_member_session_update_ip_change(
  connection: api.IConnection,
) {
  // Step 1: Register new member account
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const newMember: IEconomicDiscussionMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: {
        username: RandomGenerator.alphabets(10),
        email: memberEmail,
        password: "securePassword123",
        email_verified: true,
      } satisfies IEconomicDiscussionMember.ICreate,
    });
  typia.assert(newMember);

  // Step 2: Create initial session with original IP
  const originalIp = "192.168.1.100";
  const initialSession: IEconomicDiscussionMemberSession =
    await api.functional.economicDiscussion.member.members.sessions.create(
      connection,
      {
        memberId: newMember.member.id,
        body: {
          href: "https://economic-discussion.example.com/login",
          ip: originalIp,
          referrer: "https://economic-discussion.example.com/register",
        } satisfies IEconomicDiscussionMemberSession.ICreate,
      },
    );
  typia.assert(initialSession);

  // Verify initial session was created with correct IP
  TestValidator.equals(
    "initial session IP matches original",
    initialSession.ip,
    originalIp,
  );

  // Step 3: Update session with new IP (simulating network change)
  const newIp = "10.0.0.50";
  const updatedSession: IEconomicDiscussionMemberSession =
    await api.functional.economicDiscussion.member.members.sessions.update(
      connection,
      {
        memberId: newMember.member.id,
        sessionId: initialSession.id,
        body: {
          ip: newIp,
        } satisfies IEconomicDiscussionMemberSession.IUpdate,
      },
    );
  typia.assert(updatedSession);

  // Step 4: Verify session was updated correctly
  TestValidator.equals(
    "updated session IP matches new IP",
    updatedSession.ip,
    newIp,
  );
  TestValidator.equals(
    "session ID remains the same",
    updatedSession.id,
    initialSession.id,
  );
  TestValidator.equals(
    "member association preserved",
    updatedSession.member.id,
    newMember.member.id,
  );

  // Verify other session properties remain intact
  TestValidator.equals(
    "session href unchanged",
    updatedSession.href,
    initialSession.href,
  );
  TestValidator.equals(
    "session referrer unchanged",
    updatedSession.referrer,
    initialSession.referrer,
  );
  TestValidator.equals(
    "session creation time unchanged",
    updatedSession.created_at,
    initialSession.created_at,
  );

  // Step 5: Test edge case - clear IP address
  const sessionWithClearedIp: IEconomicDiscussionMemberSession =
    await api.functional.economicDiscussion.member.members.sessions.update(
      connection,
      {
        memberId: newMember.member.id,
        sessionId: initialSession.id,
        body: {
          ip: null,
        } satisfies IEconomicDiscussionMemberSession.IUpdate,
      },
    );
  typia.assert(sessionWithClearedIp);

  TestValidator.equals(
    "IP can be cleared to null",
    sessionWithClearedIp.ip,
    null,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEconomicDiscussionMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionMember";
import type { IEconomicDiscussionMemberSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionMemberSession";

/**
 * Test extending session expiration time when a member needs longer active
 * session duration.
 *
 * This test validates session lifecycle management for economic discussion
 * board members who require extended active periods. It verifies that a member
 * authentication session's expiration time can be updated to prevent premature
 * session termination, ensuring users can maintain continuous access to
 * community features without interruption.
 *
 * The test demonstrates the complete workflow of:
 *
 * 1. Creating a new member account through automatic registration
 * 2. Establishing an authentication session with initial context
 * 3. Updating the session's expiration timestamp to extend active duration
 * 4. Verifying the updated session maintains all member association and metadata
 *
 * This validates the session lifecycle management system's ability to handle
 * time-based session extensions, which is critical for user experience when
 * members need prolonged access to discussion features.
 */
export async function test_api_member_session_update_extend_expiration(
  connection: api.IConnection,
) {
  // Step 1: Create member account using automatic registration join
  const memberData = {
    username: RandomGenerator.name(1),
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
  } satisfies IEconomicDiscussionMember.ICreate;

  const memberAuth: IEconomicDiscussionMember.IAuthorized =
    await api.functional.auth.member.join(connection, { body: memberData });
  typia.assert(memberAuth);

  // Step 2: Create initial authentication session for the member
  const currentHref = "https://economic-discussion.example.com/member/login";
  const currentIp = "192.168.1.100";

  const sessionCreateBody = {
    href: currentHref,
    ip: currentIp,
    referrer: "https://economic-discussion.example.com/login",
  } satisfies IEconomicDiscussionMemberSession.ICreate;

  const baseSession: IEconomicDiscussionMemberSession =
    await api.functional.economicDiscussion.member.members.sessions.create(
      connection,
      {
        memberId: memberAuth.member.id,
        body: sessionCreateBody,
      },
    );
  typia.assert(baseSession);

  // Step 3: Update session to extend expiration time
  const futureExpiration = new Date(Date.now() + 7200000).toISOString(); // 2 hours from now

  const sessionUpdateBody = {
    expired_at: futureExpiration,
  } satisfies IEconomicDiscussionMemberSession.IUpdate;

  const updatedSession: IEconomicDiscussionMemberSession =
    await api.functional.economicDiscussion.member.members.sessions.update(
      connection,
      {
        memberId: memberAuth.member.id,
        sessionId: baseSession.id,
        body: sessionUpdateBody,
      },
    );
  typia.assert(updatedSession);

  // Step 4: Validate the session extension was successful
  TestValidator.equals(
    "session ID remains constant",
    updatedSession.id,
    baseSession.id,
  );
  TestValidator.equals(
    "member association maintained",
    updatedSession.member.id,
    memberAuth.member.id,
  );
  TestValidator.predicate(
    "expiration extended to future",
    () =>
      new Date(updatedSession.expired_at!).getTime() ===
      new Date(futureExpiration).getTime(),
  );

  // Validate session metadata integrity
  TestValidator.equals(
    "IP address preserved",
    updatedSession.ip,
    baseSession.ip,
  );
  TestValidator.equals(
    "href context maintained",
    updatedSession.href,
    baseSession.href,
  );
  TestValidator.notEquals(
    "expiration timestamp updated",
    updatedSession.expired_at,
    baseSession.expired_at,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEconomicDiscussionMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionMember";
import type { IEconomicDiscussionMemberSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionMemberSession";

/**
 * Test updating session referrer information for member acquisition analytics
 * after login. This tracks when users continue browsing from login success page
 * to other areas. Validates proper referrer URL updates for understanding user
 * journey patterns across the platform.
 */
export async function test_api_member_session_update_referrer_tracking(
  connection: api.IConnection,
) {
  // 1. Create a new member
  const memberCreateBody = {
    username: RandomGenerator.name(2).replace(/\s/g, "_").toLowerCase(),
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    email_verified: true,
  } satisfies IEconomicDiscussionMember.ICreate;

  const member: IEconomicDiscussionMember.IAuthorized =
    await api.functional.auth.member.join(connection, {
      body: memberCreateBody,
    });
  typia.assert(member);

  // 2. Create initial session with basic referrer data
  const sessionCreateBody = {
    href: `https://app.economydiscussion.com/login/success`,
    referrer: `https://app.economydiscussion.com/register`,
    ip: typia.random<string & tags.Format<"ipv4">>(),
  } satisfies IEconomicDiscussionMemberSession.ICreate;

  const session: IEconomicDiscussionMemberSession =
    await api.functional.economicDiscussion.member.members.sessions.create(
      connection,
      {
        memberId: member.member.id,
        body: sessionCreateBody,
      },
    );
  typia.assert(session);

  // 3. Update session referrer to track user journey from login success to dashboard
  const sessionUpdateBody = {
    referrer: `https://app.economydiscussion.com/dashboard`,
  } satisfies IEconomicDiscussionMemberSession.IUpdate;

  const updatedSession: IEconomicDiscussionMemberSession =
    await api.functional.economicDiscussion.member.members.sessions.update(
      connection,
      {
        memberId: member.member.id,
        sessionId: session.id,
        body: sessionUpdateBody,
      },
    );
  typia.assert(updatedSession);

  // 4. Validate updated referrer information
  TestValidator.equals(
    "session ID remains consistent with original session",
    updatedSession.id,
    session.id,
  );
  TestValidator.equals(
    "member ID matches authenticated member",
    updatedSession.member.id,
    member.member.id,
  );
  TestValidator.notEquals(
    "referrer URL updated from original to new destination",
    updatedSession.referrer,
    session.referrer,
  );
  TestValidator.equals(
    "new referrer matches dashboard URI",
    updatedSession.referrer,
    sessionUpdateBody.referrer,
  );
  TestValidator.equals(
    "IP address preserved during update",
    updatedSession.ip,
    session.ip,
  );
  TestValidator.equals(
    "href address preserved during update",
    updatedSession.href,
    session.href,
  );
}

