  TestValidator.notEquals(
    "moderator IDs are different",
    firstModeratorDetails.id,
    secondModeratorDetails.id,
  );
  TestValidator.notEquals(
    "moderator usernames are different",
    firstModeratorDetails.username,
    secondModeratorDetails.username,
