/**
 * Test article creation with content validation including minimum length
 * requirements and maximum field limits.
 *
 * This test validates that the economic discussion article creation properly
 * enforces content quality standards through validation rules. The test covers
 * four main validation scenarios: empty title (violates MinLength<1>), title
 * exceeding 500 characters (violates MaxLength<500>), content shorter than 10
 * characters (violates MinLength<10>), and content exceeding 50,000 characters
 * (violates MaxLength<50000>). Each scenario tests that the API returns
 * appropriate validation errors without creating invalid articles.
 *
 * Test flow:
 *
 * 1. Create member account to obtain authentication for article creation
 * 2. Test empty title validation - expect error when title field is empty string
 * 3. Test title maximum length validation - expect error when title exceeds 500
 *    characters
 * 4. Test content minimum length validation - expect error when content has less
 *    than 10 characters
 * 5. Test content maximum length validation - expect error when content exceeds
 *    50,000 characters
 * 6. Verify successful article creation with valid content meeting all
 *    requirements
 */
export async function test_api_article_creation_content_validation(
  connection: api.IConnection,
) {
  // Step 1: Create member account for authentication
  const username = RandomGenerator.alphaNumeric(10);
  const email = typia.random<string & tags.Format<"email">>();

  const member = await api.functional.auth.member.join(connection, {
    body: {
      username,
      email,
      password: "ValidPassword123!",
    } satisfies IEconomicDiscussionMember.ICreate,
  });
  typia.assert(member);

  // Step 2: Test empty title validation
  await TestValidator.error("empty title should fail validation", async () => {
    await api.functional.economicDiscussion.member.articles.create(connection, {
      body: {
        title: "",
        content: "This content meets the minimum requirement of 10 characters",
        category_ids: [typia.random<string & tags.Format<"uuid">>()],
        attachments: [],
      } satisfies IEconomicDiscussionArticle.ICreate,
    });
  });

  // Step 3: Test title maximum length validation (501 characters)
  await TestValidator.error(
    "title exceeding maximum length should fail validation",
    async () => {
      const longTitle = ArrayUtil.repeat(501, () => "a").join("");
      await api.functional.economicDiscussion.member.articles.create(
        connection,
        {
          body: {
            title: longTitle,
            content:
              "This content meets the minimum requirement of 10 characters",
            category_ids: [typia.random<string & tags.Format<"uuid">>()],
            attachments: [],
          } satisfies IEconomicDiscussionArticle.ICreate,
        },
      );
    },
  );

  // Step 4: Test content minimum length validation (9 characters)
  await TestValidator.error(
    "content shorter than minimum length should fail validation",
    async () => {
      await api.functional.economicDiscussion.member.articles.create(
        connection,
        {
          body: {
            title: "Valid Title",
            content: "Tooshort",
            category_ids: [typia.random<string & tags.Format<"uuid">>()],
            attachments: [],
          } satisfies IEconomicDiscussionArticle.ICreate,
        },
      );
    },
  );

  // Step 5: Test content maximum length validation (50,001 characters)
  await TestValidator.error(
    "content exceeding maximum length should fail validation",
    async () => {
      const longContent = ArrayUtil.repeat(50001, () => "b").join("");
      await api.functional.economicDiscussion.member.articles.create(
        connection,
        {
          body: {
            title: "Valid Title",
            content: longContent,
            category_ids: [typia.random<string & tags.Format<"uuid">>()],
            attachments: [],
          } satisfies IEconomicDiscussionArticle.ICreate,
        },
      );
