      "pending",
      "approved",
      "rejected",
    ];
    TestValidator.predicate(
      "article status is valid",
      validStatuses.includes(article.status),
    );

    TestValidator.predicate(
      "article version is positive and multiple of 0.1",
      article.version >= 0.1 && Math.round(article.version * 10) % 1 === 0,
    );
  }
}

