    finalState.id,
    category.id,
  );
  TestValidator.equals(
    "category code remains unchanged",
    finalState.code,
    category.code,
  );
  TestValidator.equals(
    "article count updated correctly",
    finalState.article_count,
    category.article_count,
  );
