import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEconomicDiscussionCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionCategory";
import type { IEconomicDiscussionModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionModerator";

/**
 * Test category creation with immediate deactivation or inactive status for
 * administrative flexibility.
 *
 * This scenario validates that moderators can create categories that aren't
 * immediately available for article assignment, allowing for content
 * organization planning and staged category rollouts. Tests proper handling of
 * inactive categories, preservation of historical references, and ensures that
 * category status management supports various administrative workflows.
 *
 * Test Steps:
 *
 * 1. Register a new moderator account
 * 2. Create an inactive category as the moderator
 * 3. Verify the inactive category properties match the request data
 * 4. Confirm is_active is false for the created category
 * 5. Test creating another category with is_active true (baseline)
 * 6. Validate proper timestamp generation and formatting
 * 7. Test category with empty description (null handling)
 *
 * The test demonstrates that categories can be created in inactive state for
 * administrative planning, ensuring proper content organization and staged
 * rollout capabilities for the discussion platform.
 */
export async function test_api_moderator_category_creation_deactivation(
  connection: api.IConnection,
) {
  // Step 1: Register a new moderator account
  const moderatorRequestBody = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    password_hash: RandomGenerator.alphaNumeric(16),
    moderation_level: RandomGenerator.pick([
      "admin",
      "moderator",
      "reviewer",
    ] as const),
    email_verified: true,
    two_factor_enabled: false,
  } satisfies IEconomicDiscussionModerator.ICreate;

  const moderator = await api.functional.auth.moderator.join(connection, {
    body: moderatorRequestBody,
  });
  typia.assert(moderator);

  // Step 2: Create an inactive category as the moderator
  const inactiveCategoryRequestBody = {
    code: RandomGenerator.alphabets(6).toLowerCase(),
    name: RandomGenerator.name(2),
    description: RandomGenerator.paragraph({
      sentences: 10,
      wordMin: 3,
      wordMax: 8,
    }),
    display_order: 1,
    is_active: false,
  } satisfies IEconomicDiscussionCategory.ICreate;

  const inactiveCategory =
    await api.functional.economicDiscussion.moderator.categories.create(
      connection,
      { body: inactiveCategoryRequestBody },
    );

  // Step 3: Verify the inactive category properties match the request data
  TestValidator.equals(
    "category code matches request",
    inactiveCategory.code,
    inactiveCategoryRequestBody.code,
  );
  TestValidator.equals(
    "category name matches request",
    inactiveCategory.name,
    inactiveCategoryRequestBody.name,
  );
  TestValidator.equals(
    "category description matches request",
    inactiveCategory.description,
    inactiveCategoryRequestBody.description,
  );
  TestValidator.equals(
    "display order matches request",
    inactiveCategory.display_order,
    inactiveCategoryRequestBody.display_order,
  );

  // Step 4: Confirm is_active is false for the created category
  TestValidator.equals(
    "category is inactive",
    inactiveCategory.is_active,
    false,
  );
  TestValidator.equals("article count is 0", inactiveCategory.article_count, 0);

  // Step 5: Create another category with is_active true (baseline comparison)
  const activeCategoryRequestBody = {
    code: RandomGenerator.alphabets(6).toLowerCase(),
    name: RandomGenerator.name(2),
    description: RandomGenerator.paragraph({
      sentences: 8,
      wordMin: 3,
      wordMax: 8,
    }),
    display_order: 2,
    is_active: true,
  } satisfies IEconomicDiscussionCategory.ICreate;

  const activeCategory =
    await api.functional.economicDiscussion.moderator.categories.create(
      connection,
      { body: activeCategoryRequestBody },
    );

  // Verify the active category has correct is_active status
  TestValidator.equals(
    "active category is active",
    activeCategory.is_active,
    true,
  );
  TestValidator.equals(
    "active category code matches request",
    activeCategory.code,
    activeCategoryRequestBody.code,
  );

  // Step 6: Validate types and formats
  typia.assert(inactiveCategory);
  typia.assert(activeCategory);

  // Validate proper timestamp generation
  TestValidator.predicate(
    "inactive category has valid created_at timestamp",
    typeof inactiveCategory.created_at === "string" &&
      inactiveCategory.created_at.length > 0,
  );
  TestValidator.predicate(
    "inactive category has valid updated_at timestamp",
    typeof inactiveCategory.updated_at === "string" &&
      inactiveCategory.updated_at.length > 0,
  );
  TestValidator.predicate(
    "active category has valid created_at timestamp",
    typeof activeCategory.created_at === "string" &&
      activeCategory.created_at.length > 0,
  );
  TestValidator.predicate(
    "active category has valid updated_at timestamp",
    typeof activeCategory.updated_at === "string" &&
      activeCategory.updated_at.length > 0,
  );

  // Step 7: Test category with empty description (null handling)
  const nullDescriptionCategoryRequestBody = {
    code: RandomGenerator.alphabets(6).toLowerCase(),
    name: RandomGenerator.name(2),
    description: null,
    display_order: 3,
    is_active: false,
  } satisfies IEconomicDiscussionCategory.ICreate;

  const nullDescriptionCategory =
    await api.functional.economicDiscussion.moderator.categories.create(
      connection,
      { body: nullDescriptionCategoryRequestBody },
    );

  TestValidator.equals(
    "category with null description has null description",
    nullDescriptionCategory.description,
    null,
  );
  TestValidator.equals(
    "category with null description is inactive",
    nullDescriptionCategory.is_active,
    false,
  );
  typia.assert(nullDescriptionCategory);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAttachmentFilename } from "@ORGANIZATION/PROJECT-api/lib/structures/IAttachmentFilename";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEconomicDiscussionArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionArticle";
import type { IEconomicDiscussionAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionAttachment";
import type { IEconomicDiscussionAttachmentFileType } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionAttachmentFileType";
import type { IEconomicDiscussionAttachments } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionAttachments";
import type { IEconomicDiscussionCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionCategories";
import type { IEconomicDiscussionMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionMember";
import type { IEconomicDiscussionMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionMembers";
import type { IEconomicDiscussionModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionModerators";
import type { IFileSize } from "@ORGANIZATION/PROJECT-api/lib/structures/IFileSize";
import type { IFileType } from "@ORGANIZATION/PROJECT-api/lib/structures/IFileType";
import type { IMimeType } from "@ORGANIZATION/PROJECT-api/lib/structures/IMimeType";

/**
 * Test successful upload of image attachment to member's own article. Validates
 * file type validation for JPEG images, size limits (up to 5MB), secure upload
 * process, and metadata persistence. Also verifies attachment count validation
 * (max 5 per article) and checks that uploaded attachment appears in article's
 * attachment list.
 */
export async function test_api_member_article_attachment_upload_image(
  connection: api.IConnection,
) {
  // Step 1: Register as a member to get authentication
  const username = RandomGenerator.name();
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(12);

  const memberAuth = await api.functional.auth.member.join(connection, {
    body: {
      username,
      email,
      password,
    } satisfies IEconomicDiscussionMember.ICreate,
  });
  typia.assert(memberAuth);

  // Step 2: Create an article to attach files to
  const articleTitle = RandomGenerator.paragraph({
    sentences: 3,
    wordMin: 4,
    wordMax: 8,
  });
  const articleContent = RandomGenerator.content({
    paragraphs: 3,
    sentenceMin: 8,
    sentenceMax: 15,
  });
  const categoryIds = [typia.random<string & tags.Format<"uuid">>()];

  const article =
    await api.functional.economicDiscussion.member.articles.create(connection, {
      body: {
        title: articleTitle,
        content: articleContent,
        category_ids: categoryIds,
      } satisfies IEconomicDiscussionArticle.ICreate,
    });
  typia.assert(article);

  // Step 3: Upload multiple JPEG image attachments
  const attachmentCount = 3; // Upload 3 images to test multiple attachments
  const uploadedAttachments: IEconomicDiscussionAttachment[] = [];

  for (let i = 0; i < attachmentCount; i++) {
    const filename = `image_${i + 1}.jpg` as IAttachmentFilename;
    const fileSize = typia.random<
      number & tags.Type<"int32"> & tags.Minimum<1000> & tags.Maximum<5242880>
    >(); // 1KB to 5MB
    const mimeType: IMimeType = "image/jpeg";
    const fileType: IEconomicDiscussionAttachmentFileType = "image";

    const attachment =
      await api.functional.economicDiscussion.member.articles.attachments.create(
        connection,
        {
          articleId: article.id,
          body: {
            filename,
            file_size: fileSize satisfies number as number,
            mime_type: mimeType,
            file_type: fileType,
          } satisfies IEconomicDiscussionAttachment.ICreate,
        },
      );
    typia.assert(attachment);

    uploadedAttachments.push(attachment);

    // Verify attachment properties
    TestValidator.equals(
      `attachment ${i + 1} filename matches`,
      attachment.filename,
      filename,
    );
    TestValidator.equals(
      `attachment ${i + 1} file size matches`,
      attachment.file_size,
      fileSize,
    );
    TestValidator.equals(
      `attachment ${i + 1} MIME type matches`,
      attachment.mime_type,
      mimeType,
    );
    TestValidator.equals(
      `attachment ${i + 1} file type matches`,
      attachment.file_type,
      fileType,
    );
    TestValidator.predicate(
      `attachment ${i + 1} is assigned to correct article`,
      attachment.article.id === article.id,
    );
    TestValidator.predicate(
      `attachment ${i + 1} has upload timestamp`,
      typeof attachment.uploaded_at === "string",
    );
    TestValidator.predicate(
      `attachment ${i + 1} has scan status`,
      typeof attachment.is_scanned === "boolean",
    );
  }

  // Step 4: Verify total attachment count tracking
  TestValidator.equals(
    "correct number of attachments uploaded",
    uploadedAttachments.length,
    attachmentCount,
  );

  // Step 5: Validate attachment metadata consistency
  uploadedAttachments.forEach((attachment, index) => {
    TestValidator.equals(
      `attachment ${index + 1} ID is valid UUID`,
      typeof attachment.id === "string" && attachment.id.length === 36,
      true,
    );
    TestValidator.predicate(
      `attachment ${index + 1} has article summary`,
      attachment.article !== undefined,
    );
    TestValidator.equals(
      `attachment ${index + 1} article ID matches`,
      attachment.article.id,
      article.id,
    );
  });

  // Step 6: Test file size validation boundaries
  const validFileSizes = uploadedAttachments.map((att) => att.file_size);
  const minSize = Math.min(...validFileSizes);
  const maxSize = Math.max(...validFileSizes);

  TestValidator.predicate(
    "all file sizes are positive",
    validFileSizes.every((size) => size > 0),
  );
  TestValidator.predicate(
    "all file sizes are within 5MB limit",
    validFileSizes.every((size) => size <= 5242880),
  );
  TestValidator.predicate("file sizes show variation", maxSize > minSize);

  // Log successful test completion with details
  console.log(
    `Successfully uploaded ${attachmentCount} image attachments to article`,
    {
      articleId: article.id,
      articleTitle: article.title,
      memberUsername: memberAuth.member.username,
      totalAttachments: uploadedAttachments.length,
    },
  );
}

