import type { IEconomicDiscussionAttachments } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionAttachments";
import type { IEconomicDiscussionCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionCategories";
import type { IEconomicDiscussionMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionMember";
import type { IEconomicDiscussionMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionMembers";
import type { IEconomicDiscussionModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionModerators";
import type { IFileSize } from "@ORGANIZATION/PROJECT-api/lib/structures/IFileSize";
import type { IFileType } from "@ORGANIZATION/PROJECT-api/lib/structures/IFileType";
import type { IMimeType } from "@ORGANIZATION/PROJECT-api/lib/structures/IMimeType";

/**
 * Test file type validation and rejection for unsupported formats for economic
 * discussion article attachments.
 *
 * This test validates the security mechanism that enforces legitimate file
 * uploads while rejecting dangerous file types through the economic discussion
 * platform.
 *
 * Test flow:
 *
 * 1. Create authenticated member with valid credentials
 * 2. Create test article with economic discussion content
 * 3. Upload legitimate files (document, image, spreadsheet) to verify acceptance
 * 4. Test rejection of security-dangerous files (executables, scripts)
 * 5. Confirm all upload operations respect the 5 attachment limit per article
 *
 * Business validation:
 *
 * - File type categories limited to image/document/spreadsheet only
 * - MIME type validation against whitelisted formats
 * - Security scanning initiation for accepted uploads
 * - Proper error feedback for unsupported dangerous file types
 */
export async function test_api_member_article_attachment_type_validation(
  connection: api.IConnection,
) {
  // Step 1: Create member account for authentication
  const memberAuth = await api.functional.auth.member.join(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      password: "TestPassword123",
    } satisfies IEconomicDiscussionMember.ICreate,
  });
  typia.assert(memberAuth);

  // Step 2: Create test article for attachment associations
  const article =
    await api.functional.economicDiscussion.member.articles.create(connection, {
      body: {
        title: "Economic Impact Analysis with Supporting Documentation",
        content: RandomGenerator.content({
          paragraphs: 2,
          sentenceMin: 8,
          sentenceMax: 12,
        }),
        category_ids: [typia.random<string & tags.Format<"uuid">>()],
      } satisfies IEconomicDiscussionArticle.ICreate,
    });
  typia.assert(article);

  // Step 3: Test legitimate attachment upload acceptance
  const legalDocuments = [
    {
      filename: "market_analysis_report.pdf" as IAttachmentFilename,
      file_size: typia.random<
        number & tags.Type<"uint32"> & tags.Minimum<500> & tags.Maximum<2000000>
      >(),
      file_type: "document" as IEconomicDiscussionAttachmentFileType,
      mime_type: "application/pdf" as IMimeType,
    },
    {
      filename: "chart_visualization.png" as IAttachmentFilename,
      file_size: typia.random<
        number & tags.Type<"uint32"> & tags.Minimum<300> & tags.Maximum<1500000>
      >(),
      file_type: "image" as IEconomicDiscussionAttachmentFileType,
      mime_type: "image/png" as IMimeType,
    },
  ] as const;

  const attachments: IEconomicDiscussionAttachment[] = [];

  for (const doc of legalDocuments) {
    const attachment =
      await api.functional.economicDiscussion.member.articles.attachments.create(
        connection,
        {
          articleId: article.id,
          body: doc satisfies IEconomicDiscussionAttachments.ICreate,
        },
      );
    typia.assert(attachment);

    TestValidator.equals(
      "article belongs to created attachment",
      attachment.article.id,
      article.id,
    );
    TestValidator.equals(
      "correct file type assigned",
      attachment.file_type,
      doc.file_type,
    );
    attachments.push(attachment);
  }

  // Step 4: Test rejection of security-threatening file uploads
  const securityViolations = [
    {
      filename: "utility_tool.exe" as IAttachmentFilename,
      file_size: 2560,
      file_type: "document" as IEconomicDiscussionAttachmentFileType,
      mime_type: "application/octet-stream" as IMimeType, // Blocked: unknown binary
    },
    {
      filename: "data_script.js" as IAttachmentFilename,
      file_size: 1024,
      file_type: "document" as IEconomicDiscussionAttachmentFileType,
      mime_type: "application/javascript" as IMimeType, // Blocked: executable script
    },
  ];

  for (const malware of securityViolations) {
    await TestValidator.error(
      "dangerous file types should be rejected by security validation",
      async () => {
        await api.functional.economicDiscussion.member.articles.attachments.create(
          connection,
          {
            articleId: article.id,
            body: malware satisfies IEconomicDiscussionAttachments.ICreate,
          },
        );
      },
    );
  }

  // Step 5: Confirm all successful uploads are present
  TestValidator.equals("total attachment count", attachments.length, 2);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAttachmentFilename } from "@ORGANIZATION/PROJECT-api/lib/structures/IAttachmentFilename";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEconomicDiscussionArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionArticle";
import type { IEconomicDiscussionAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionAttachment";
import type { IEconomicDiscussionAttachmentFileType } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionAttachmentFileType";
import type { IEconomicDiscussionAttachments } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionAttachments";
import type { IEconomicDiscussionCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionCategories";
import type { IEconomicDiscussionMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionMember";
import type { IEconomicDiscussionMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionMembers";
import type { IEconomicDiscussionModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionModerators";
import type { IFileSize } from "@ORGANIZATION/PROJECT-api/lib/structures/IFileSize";
import type { IFileType } from "@ORGANIZATION/PROJECT-api/lib/structures/IFileType";
import type { IMimeType } from "@ORGANIZATION/PROJECT-api/lib/structures/IMimeType";

/**
 * Test file size validation by uploading oversized files to verify appropriate
 * rejection and size limit enforcement. Tests both image (5MB+) and document
 * (20MB+) size restrictions with appropriate error responses.
 */
export async function test_api_member_article_attachment_size_limit(
  connection: api.IConnection,
) {
  // 1. Register a new member account
  const memberAuth = await api.functional.auth.member.join(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: RandomGenerator.name(2).replace(" ", "") + "@test.com",
      password: "password123",
    } satisfies IEconomicDiscussionMember.ICreate,
  });
  typia.assert(memberAuth);

  // 2. Create an article for testing attachment uploads
  const article =
    await api.functional.economicDiscussion.member.articles.create(connection, {
      body: {
        title: "Testing File Size Limits",
        content:
          "This article tests the file upload size restrictions for different attachment types.",
        category_ids: [typia.random<string & tags.Format<"uuid">>()],
      } satisfies IEconomicDiscussionArticle.ICreate,
    });
  typia.assert(article);

  // 3. Test oversized image file (6MB - exceeding 5MB limit)
  await TestValidator.error("should reject oversized image file", async () => {
    await api.functional.economicDiscussion.member.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: {
          filename: "oversized-image.jpg" satisfies IAttachmentFilename,
          file_size: 6291456 satisfies IFileSize, // 6MB (exceeds 5MB limit)
          file_type: "image" satisfies IFileType,
          mime_type: "image/jpeg" satisfies IMimeType,
        } satisfies IEconomicDiscussionAttachment.ICreate,
      },
    );
  });

  // 4. Test oversized document file (25MB - exceeding 20MB limit)
  await TestValidator.error(
    "should reject oversized document file",
    async () => {
      await api.functional.economicDiscussion.member.articles.attachments.create(
        connection,
        {
          articleId: article.id,
          body: {
            filename: "oversized-document.pdf" satisfies IAttachmentFilename,
            file_size: 26214400 satisfies IFileSize, // 25MB (exceeds 20MB limit)
            file_type: "document" satisfies IFileType,
            mime_type: "application/pdf" satisfies IMimeType,
          } satisfies IEconomicDiscussionAttachment.ICreate,
        },
      );
    },
  );

  // 5. Test oversized spreadsheet file (25MB - exceeding 20MB limit)
  await TestValidator.error(
    "should reject oversized spreadsheet file",
    async () => {
      await api.functional.economicDiscussion.member.articles.attachments.create(
        connection,
        {
          articleId: article.id,
          body: {
            filename:
              "oversized-spreadsheet.xlsx" satisfies IAttachmentFilename,
            file_size: 26214400 satisfies IFileSize, // 25MB (exceeds 20MB limit)
            file_type: "spreadsheet" satisfies IFileType,
            mime_type:
              "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" satisfies IMimeType,
          } satisfies IEconomicDiscussionAttachment.ICreate,
        },
      );
    },
  );

  // 6. Test valid sized files should succeed
  const validImage =
    await api.functional.economicDiscussion.member.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: {
          filename: "valid-image.jpg" satisfies IAttachmentFilename,
          file_size: 4718592 satisfies IFileSize, // 4.5MB (within 5MB limit)
          file_type: "image" satisfies IFileType,
          mime_type: "image/jpeg" satisfies IMimeType,
        } satisfies IEconomicDiscussionAttachment.ICreate,
      },
    );
  typia.assert(validImage);

  const validDocument =
    await api.functional.economicDiscussion.member.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: {
          filename: "valid-document.pdf" satisfies IAttachmentFilename,
          file_size: 10485760 satisfies IFileSize, // 10MB (within 20MB limit)
          file_type: "document" satisfies IFileType,
          mime_type: "application/pdf" satisfies IMimeType,
        } satisfies IEconomicDiscussionAttachment.ICreate,
      },
    );
  typia.assert(validDocument);

  // 7. Verify valid attachments are created successfully
  TestValidator.equals(
    "image attachment file size should be 4.5MB",
    validImage.file_size,
    4718592,
  );
  TestValidator.equals(
    "document attachment file size should be 10MB",
    validDocument.file_size,
    10485760,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAttachmentFilename } from "@ORGANIZATION/PROJECT-api/lib/structures/IAttachmentFilename";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEconomicDiscussionArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionArticle";
import type { IEconomicDiscussionAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionAttachment";
import type { IEconomicDiscussionAttachmentFileType } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionAttachmentFileType";
import type { IEconomicDiscussionAttachments } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionAttachments";
import type { IEconomicDiscussionCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionCategories";
import type { IEconomicDiscussionMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionMember";
import type { IEconomicDiscussionMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionMembers";
import type { IEconomicDiscussionModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionModerators";
import type { IFileSize } from "@ORGANIZATION/PROJECT-api/lib/structures/IFileSize";
import type { IFileType } from "@ORGANIZATION/PROJECT-api/lib/structures/IFileType";
import type { IMimeType } from "@ORGANIZATION/PROJECT-api/lib/structures/IMimeType";

/**
 * Test limiting attachments to maximum 5 per article.
 *
 * This test validates the system's enforcement of the 5-attachment limit per
 * economic discussion article. It creates a complete workflow including member
 * registration, article creation, uploading exactly 5 attachments, and then
 * attempting to add a 6th attachment to verify the limit is properly enforced.
 * The test ensures that the system provides appropriate error response when the
 * maximum capacity is exceeded.
 *
 * 1. Register a new member account
 * 2. Create a new economic discussion article
 * 3. Upload 5 file attachments (reaching the maximum)
 * 4. Attempt to upload a 6th attachment to test limit enforcement
 * 5. Verify proper error handling when limit is exceeded
 */
export async function test_api_member_article_attachment_max_count(
  connection: api.IConnection,
) {
  // Register a new member
  const username = RandomGenerator.alphabets(12);
  const email = `test-${RandomGenerator.alphabets(8)}@example.com`;
  const member = await api.functional.auth.member.join(connection, {
    body: {
      username,
      email,
      password: "strongPassword123",
    } satisfies IEconomicDiscussionMember.ICreate,
  });
  typia.assert(member);

  // Create a new economic discussion article
  const title = RandomGenerator.paragraph({ sentences: 3 });
  const content = RandomGenerator.content({
    paragraphs: 2,
    sentenceMin: 15,
    sentenceMax: 25,
  });
  const fileTypes: IEconomicDiscussionAttachmentFileType[] = [
    "image",
    "document",
    "spreadsheet",
  ];
  const mimeTypes: IMimeType[] = [
    "image/jpeg",
    "image/png",
    "application/pdf",
    "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
  ];

  const article =
    await api.functional.economicDiscussion.member.articles.create(connection, {
      body: {
        title,
        content,
        category_ids: [typia.random<string & tags.Format<"uuid">>()],
        attachments: [],
      } satisfies IEconomicDiscussionArticle.ICreate,
    });
  typia.assert(article);

  // Upload exactly 5 attachments to reach the maximum limit
  const attachments: IEconomicDiscussionAttachment[] = [];

  for (let i = 0; i < 5; i++) {
    const fileName: IAttachmentFilename = `${RandomGenerator.alphabets(8)}_${i}.pdf`;
    const fileType = i < 3 ? fileTypes[1] : fileTypes[0]; // Mix of document and image types
    const mimeType = i < 3 ? mimeTypes[2] : mimeTypes[i % 2]; // PDF or imageMIME types

    const attachment =
      await api.functional.economicDiscussion.member.articles.attachments.create(
        connection,
        {
          articleId: article.id,
          body: {
            filename: fileName,
            file_size: 1024 * 1024 * (i + 1), // 1MB to 5MB incremental sizes
            file_type: fileType,
            mime_type: mimeType,
          } satisfies IEconomicDiscussionAttachment.ICreate,
        },
      );
    typia.assert(attachment);
    attachments.push(attachment);

    // Verify each attachment was created successfully
    TestValidator.equals(
      "attachment count after creation",
      attachments.length,
      i + 1,
    );
    TestValidator.equals("attachment filename", attachment.filename, fileName);
    TestValidator.equals(
      "attachment article ID",
      attachment.article.id,
      article.id,
    );
  }

  // Verify we have exactly 5 attachments
  TestValidator.equals(
    "total attachments before limit test",
    attachments.length,
    5,
  );

  // Attempt to upload a 6th attachment (should fail)
  await TestValidator.error(
    "6th attachment should fail - attachment limit reached",
    async () => {
      await api.functional.economicDiscussion.member.articles.attachments.create(
        connection,
        {
          articleId: article.id,
          body: {
            filename: "over_limit_test.pdf",
            file_size: 1024 * 1024,
            file_type: "document",
            mime_type: "application/pdf",
          } satisfies IEconomicDiscussionAttachment.ICreate,
        },
      );
    },
  );

  // Verify article still has only 5 attachments
  TestValidator.equals(
    "article should still have only 5 attachments",
    attachments.length,
    5,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
