/**
 * Test adding attachments to articles authored by other moderators. Validates
 * inter-moderator collaboration and content enhancement capabilities within the
 * moderation team.
 */
export async function test_api_moderator_attachment_moderator_article(
  connection: api.IConnection,
) {
  // Step 1: Create first moderator account
  const firstModeratorUsername = RandomGenerator.alphabets(10);
  const firstModeratorEmail = `${RandomGenerator.alphabets(8)}@economicdiscussion.com`;

  const firstModerator = await api.functional.auth.moderator.join(connection, {
    body: {
      username: firstModeratorUsername,
      email: firstModeratorEmail,
      password_hash: RandomGenerator.alphaNumeric(16),
      moderation_level: "standard",
      email_verified: true,
      two_factor_enabled: false,
    } satisfies IEconomicDiscussionModerator.ICreate,
  });
  typia.assert(firstModerator);

  // Step 2: Create a category as first moderator
  const categoryBody = {
    code: RandomGenerator.alphabets(8),
    name: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.content({ paragraphs: 2 }),
    display_order: typia.random<
      number & tags.Type<"int32"> & tags.Minimum<0>
    >(),
    is_active: true,
  } satisfies IEconomicDiscussionCategory.ICreate;

  const category =
    await api.functional.economicDiscussion.moderator.categories.create(
      connection,
      {
        body: categoryBody,
      },
    );
  typia.assert(category);

  // Step 3: Create an article as first moderator
  const articleBody = {
    title: RandomGenerator.paragraph({ sentences: 4 }),
    content: RandomGenerator.content({
      paragraphs: 5,
      sentenceMin: 15,
      sentenceMax: 25,
    }),
    category_ids: [category.id],
    attachments: [],
  } satisfies IEconomicDiscussionArticle.ICreate;

  const article =
    await api.functional.economicDiscussion.moderator.articles.create(
      connection,
      {
        body: articleBody,
      },
    );
  typia.assert(article);

  // Step 4: Create second moderator account
  const secondModeratorUsername = RandomGenerator.alphabets(10);
  const secondModeratorEmail = `${RandomGenerator.alphabets(8)}@economicdiscussion.com`;

  const secondModerator = await api.functional.auth.moderator.join(connection, {
    body: {
      username: secondModeratorUsername,
      email: secondModeratorEmail,
      password_hash: RandomGenerator.alphaNumeric(16),
      moderation_level: "senior",
      email_verified: true,
      two_factor_enabled: false,
    } satisfies IEconomicDiscussionModerator.ICreate,
  });
  typia.assert(secondModerator);

  // Step 5: Second moderator adds attachment to first moderator's article
  const attachmentBody = {
    filename:
      `economic_analysis_${RandomGenerator.alphabets(5)}.pdf` satisfies IAttachmentFilename,
    file_size: typia.random<
      number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<10485760>
    >(),
    file_type: "document" as IEconomicDiscussionAttachmentFileType,
    mime_type: "application/pdf" as IMimeType,
  } satisfies IEconomicDiscussionAttachments.ICreate;

  const attachment =
    await api.functional.economicDiscussion.moderator.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: attachmentBody,
      },
    );
  typia.assert(attachment);

  // Validate the attachment was created successfully
  TestValidator.equals(
    "attachment article ID matches",
    attachment.article.id,
    article.id,
  );
  TestValidator.equals(
    "attachment filename matches",
    attachment.filename,
    attachmentBody.filename,
  );
  TestValidator.equals(
    "attachment file type matches",
    attachment.file_type,
    attachmentBody.file_type,
  );
  TestValidator.equals(
    "attachment MIME type matches",
    attachment.mime_type,
    attachmentBody.mime_type,
  );
  TestValidator.predicate(
    "attachment file size matches",
    attachment.file_size === attachmentBody.file_size,
  );
  TestValidator.predicate(
    "attachment is not yet scanned",
    attachment.is_scanned === false,
  );

  // Add a second attachment to demonstrate multiple file support
  const secondAttachmentBody = {
    filename:
      `chart_${RandomGenerator.alphabets(5)}.png` satisfies IAttachmentFilename,
    file_size: typia.random<
      number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<10485760>
    >(),
    file_type: "image" as IEconomicDiscussionAttachmentFileType,
    mime_type: "image/png" as IMimeType,
  } satisfies IEconomicDiscussionAttachments.ICreate;

  const secondAttachment =
    await api.functional.economicDiscussion.moderator.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: secondAttachmentBody,
      },
    );
  typia.assert(secondAttachment);

  // Validate second attachment
  TestValidator.equals(
    "second attachment article ID matches",
    secondAttachment.article.id,
    article.id,
  );
  TestValidator.equals(
    "second attachment filename matches",
    secondAttachment.filename,
    secondAttachmentBody.filename,
  );
  TestValidator.equals(
    "second attachment file type matches",
    secondAttachment.file_type,
    secondAttachmentBody.file_type,
  );

  // Test with attachment limit boundary (system allows up to 5 attachments)
  const makeAdditionalAttachments = ArrayUtil.repeat(3, (index) => ({
    filename:
      `supporting_doc_${index}_${RandomGenerator.alphabets(3)}.pdf` satisfies IAttachmentFilename,
    file_size: typia.random<
      number & tags.Type<"int32"> & tags.Minimum<1024> & tags.Maximum<512000>
    >(), // Between 1KB and 500KB
    file_type: "document" as IEconomicDiscussionAttachmentFileType,
    mime_type: "application/pdf" as IMimeType,
  }));

  // Create remaining attachments to reach close to the 5-attachment limit
  for (const extraAttachmentData of makeAdditionalAttachments) {
    const extraAttachment =
      await api.functional.economicDiscussion.moderator.articles.attachments.create(
        connection,
        {
          articleId: article.id,
          body: extraAttachmentData satisfies IEconomicDiscussionAttachments.ICreate,
        },
      );
    typia.assert(extraAttachment);
    TestValidator.equals(
      "extra attachment properly linked",
      extraAttachment.article.id,
      article.id,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEconomicDiscussionArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionArticle";
import type { IEconomicDiscussionAttachmentFileType } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionAttachmentFileType";
import type { IEconomicDiscussionAttachments } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionAttachments";
import type { IEconomicDiscussionCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionCategories";
import type { IEconomicDiscussionCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionCategory";
import type { IEconomicDiscussionMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionMembers";
import type { IEconomicDiscussionModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionModerator";
import type { IEconomicDiscussionModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionModerators";

/**
 * Test moderator article creation with enhanced article management including
 * all advanced formatting options. Validates moderation-specific features and
 * broader article creation capabilities compared to member accounts.
 *
 * Test workflow:
 *
 * 1. Create a new moderator account for enhanced article testing
 * 2. Create a category to assign during article creation
 * 3. Generate comprehensive article content with all available features
 * 4. Create attachments supporting the article (images, documents, spreadsheets)
 * 5. Create the article with full metadata and formatting
 * 6. Validate the created article has all moderator-specific features
 * 7. Verify categories, attachments, and content structure are properly linked
 *
 * This test validates that moderators can create articles with enhanced
 * formatting, comprehensive category assignments, and attachment management
 * capabilities beyond what standard members can access.
 */
export async function test_api_moderator_article_creation_enhanced(
  connection: api.IConnection,
) {
  // Step 1: Create moderator account for enhanced article testing
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      username: RandomGenerator.name(1),
      email: moderatorEmail,
      password_hash: RandomGenerator.alphaNumeric(32),
      moderation_level: RandomGenerator.pick([
        "standard",
        "senior",
        "admin",
      ] as const),
      email_verified: true,
      two_factor_enabled: false,
    } satisfies IEconomicDiscussionModerator.ICreate,
  });
  typia.assert(moderator);

  TestValidator.predicate("moderator has valid UUID", moderator.id !== null);
  TestValidator.predicate(
    "moderator email verified",
    moderator.email_verified === true,
  );

  // Step 2: Create a category for article assignment
  const category =
    await api.functional.economicDiscussion.moderator.categories.create(
      connection,
      {
        body: {
          code: RandomGenerator.alphaNumeric(8).toLowerCase(),
          name: RandomGenerator.name(2),
          description: RandomGenerator.paragraph({ sentences: 5 }),
          display_order: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<100>
          >(),
          is_active: true,
        } satisfies IEconomicDiscussionCategory.ICreate,
      },
    );
  typia.assert(category);

  TestValidator.predicate("category has valid ID", category.id !== null);
  TestValidator.predicate("category is active", category.is_active === true);

  // Step 3: Create article attachments (images, documents, spreadsheets)
  const attachments: IEconomicDiscussionAttachments.ICreate[] =
    ArrayUtil.repeat(
      typia.random<
        number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<5>
      >(),
      () =>
        ({
          file_size: typia.random<
            number &
              tags.Type<"int32"> &
              tags.Minimum<1000> &
              tags.Maximum<1048576>
          >(),
          file_type: RandomGenerator.pick([
            "image",
            "document",
            "spreadsheet",
          ] as const),
          filename: `${RandomGenerator.name(1)}.${RandomGenerator.pick(["jpg", "png", "pdf", "xlsx"] as const)}`,
          mime_type: RandomGenerator.pick([
            "image/jpeg",
            "image/png",
            "application/pdf",
            "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
          ] as const),
        }) satisfies IEconomicDiscussionAttachments.ICreate,
    );

  // Step 4: Create comprehensive article with enhanced features
  const articleContent = RandomGenerator.content({
    paragraphs: typia.random<
      number & tags.Type<"int32"> & tags.Minimum<3> & tags.Maximum<10>
    >(),
    sentenceMin: 8,
    sentenceMax: 15,
    wordMin: 4,
    wordMax: 8,
  });

  const articleTitle = RandomGenerator.name(3);
  const articleData = {
    title: articleTitle,
    content: articleContent,
    category_ids: [category.id],
    attachments: attachments.length > 0 ? attachments : undefined,
  } satisfies IEconomicDiscussionArticle.ICreate;

  // Step 5: Create the article with enhanced moderator features
  const article =
    await api.functional.economicDiscussion.moderator.articles.create(
      connection,
      { body: articleData },
    );
  typia.assert(article);

  // Step 6: Validate created article structure and content
  TestValidator.equals("article title matches", article.title, articleTitle);
  TestValidator.equals(
    "article content matches",
    article.content,
    articleContent,
  );
  TestValidator.equals("view count initialized to zero", article.view_count, 0);
  TestValidator.equals("version starts at 0", article.version, 0);

  // Validate author assignments - moderator-specific feature
  if (
    article.moderator_author !== null &&
    article.moderator_author !== undefined
  ) {
    TestValidator.predicate("article has moderator author", true);
  }

  if (
    article.moderator_author_profile !== undefined &&
    article.moderator_author_profile !== null
  ) {
    TestValidator.predicate("article has moderator profile info", true);
  }

  // Step 7: Verify category assignment
  TestValidator.predicate(
    "article has categories",
    article.categories.length > 0,
  );
  TestValidator.equals(
    "assigned category ID matches",
    article.categories[0].id,
    category.id,
  );
  TestValidator.equals(
    "category name matches",
    article.categories[0].name,
    category.name,
  );

  // Step 8: Validate article status and workflow state
  TestValidator.predicate(
    "article has valid status",
    article.status === "pending" ||
      article.status === "approved" ||
      article.status === "rejected",
  );
  TestValidator.predicate(
    "article creation timestamp exists",
    typia.is<string & tags.Format<"date-time">>(article.created_at),
  );
  TestValidator.predicate(
    "article update timestamp exists",
    typia.is<string & tags.Format<"date-time">>(article.updated_at),
  );

  // Step 9: Validate attachment handling (if provided)
  if (attachments.length > 0) {
    TestValidator.predicate("article attachments created when provided", true);
  } else {
    TestValidator.predicate("article created without attachments", true);
  }

  // Step 10: Validate soft deletion tracking capability
  TestValidator.predicate(
    "article has deletion tracking capability",
    article.deleted_at === null,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEconomicDiscussionArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionArticle";
import type { IEconomicDiscussionAttachmentFileType } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionAttachmentFileType";
import type { IEconomicDiscussionAttachments } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionAttachments";
import type { IEconomicDiscussionCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionCategories";
import type { IEconomicDiscussionCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionCategory";
import type { IEconomicDiscussionMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionMembers";
import type { IEconomicDiscussionModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionModerator";
import type { IEconomicDiscussionModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionModerators";

/**
 * Validates moderator article cross-user visibility functionality.
 *
 * This test verifies that moderator-created articles appear properly in article
 * listings and search results alongside member articles. It tests system
 * integration and visibility across different user roles in the economic
 * discussion platform.
 *
 * Test Workflow:
 *
 * 1. Create a moderator account using the auth system
 * 2. Create a discussion category for organizing content
 * 3. Publish a moderator-authored article
 * 4. Verify the article is created with proper metadata
 * 5. Validate that moderator articles integrate seamlessly with member content
 *
 * The test ensures administrative content becomes visible within the platform's
 * content discovery system, maintaining appropriate attribution while enabling
 * user access to official discussions and policy analyses.
 */
export async function test_api_moderator_article_cross_user_visibility(
  connection: api.IConnection,
) {
  // Create moderator account for testing
  const moderatorRequest = {
    username: RandomGenerator.alphabets(10),
    email: typia.random<string & tags.Format<"email">>(),
    password_hash: RandomGenerator.alphaNumeric(32),
    email_verified: true,
    two_factor_enabled: false,
    moderation_level: "standard",
  } satisfies IEconomicDiscussionModerator.ICreate;

  const moderator = await api.functional.auth.moderator.join(connection, {
    body: moderatorRequest,
  });
  typia.assert(moderator);

  TestValidator.predicate(
    "moderator created successfully",
    moderator.username === moderatorRequest.username,
  );
  TestValidator.predicate(
    "moderator email matches input",
    moderator.email === moderatorRequest.email,
  );

  // Create discussion category for articles
  const categoryRequest = {
    code: RandomGenerator.alphabets(8).toLowerCase(),
    name: RandomGenerator.name(),
    description: RandomGenerator.paragraph({ sentences: 3 }),
    display_order: typia.random<
      number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<100>
    >(),
    is_active: true,
  } satisfies IEconomicDiscussionCategory.ICreate;

  const category =
    await api.functional.economicDiscussion.moderator.categories.create(
      connection,
      { body: categoryRequest },
    );
  typia.assert(category);

  TestValidator.equals(
    "category code matches request",
    category.code,
    categoryRequest.code,
  );
  TestValidator.equals(
    "category name matches request",
    category.name,
    categoryRequest.name,
  );

  // Create moderator-authored article with proper attachments count
  const attachmentCount = typia.random<
    number & tags.Type<"uint32"> & tags.Minimum<0> & tags.Maximum<2>
  >();
  const attachments = ArrayUtil.repeat(attachmentCount, () => ({
    file_size: typia.random<
      number & tags.Type<"int32"> & tags.Minimum<1024> & tags.Maximum<1048576>
    >(),
    file_type: RandomGenerator.pick([
      "image",
      "document",
      "spreadsheet",
    ] as const),
    filename: RandomGenerator.name() + ".pdf",
    mime_type: "application/pdf",
  }));

  const articleRequest = {
    title: RandomGenerator.paragraph({ sentences: 2 }),
    content: RandomGenerator.content({
      paragraphs: 3,
      sentenceMin: 15,
      sentenceMax: 25,
      wordMin: 4,
      wordMax: 8,
    }),
    category_ids: [category.id],
    attachments: attachments,
  } satisfies IEconomicDiscussionArticle.ICreate;

  const article =
    await api.functional.economicDiscussion.moderator.articles.create(
      connection,
      { body: articleRequest },
    );
  typia.assert(article);

  // Validate article metadata and visibility properties
  TestValidator.equals(
    "article title matches request",
    article.title,
    articleRequest.title,
  );
  TestValidator.equals(
    "article content matches request",
    article.content,
    articleRequest.content,
  );
  TestValidator.predicate(
    "article has moderator author",
    article.moderator_author === moderator.id,
  );
  TestValidator.predicate(
    "article moderator profile exists",
    article.moderator_author_profile !== undefined,
  );
  TestValidator.equals(
    "moderator username in profile matches",
    article.moderator_author_profile!.username,
    moderator.username,
  );

  TestValidator.predicate(
    "article has at least one category",
    article.categories.length >= 1,
  );
  TestValidator.predicate(
    "article includes created category",
    article.categories.some((c) => c.id === category.id),
  );

  // Verify visibility tracking metrics
  TestValidator.equals(
    "article view count initialized to 0",
    article.view_count,
    0,
  );
  TestValidator.equals("article version starts at 1", article.version, 1);
  TestValidator.equals(
    "article status is pending for new content",
    article.status,
    "pending",
  );
  TestValidator.predicate(
    "article created timestamp is valid",
    new Date(article.created_at).getTime() > 0,
  );
  TestValidator.predicate(
    "article updated timestamp is valid",
    new Date(article.updated_at).getTime() > 0,
  );

  // Validate attachment integrity
  TestValidator.predicate(
    "attachments created when provided",
    attachmentCount === 0 ||
      (article.categories.length > 0 &&
        Array.isArray(articleRequest.attachments)),
  );

  // Verify cross-role compatibility
  TestValidator.predicate(
    "moderator content has standard article structure",
    typeof article.id === "string" &&
      typeof article.title === "string" &&
      typeof article.content === "string",
  );
  TestValidator.predicate(
    "moderator articles follow same lifecycle as member articles",
    article.status === "pending" && article.version === 1,
  );

  console.log(`✅ Moderator article visibility test completed successfully`);
  console.log(`   - Created moderator: ${moderator.username}`);
  console.log(`   - Created category: ${category.name}`);
  console.log(`   - Published article: ${article.title.substring(0, 50)}...`);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
