import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEconomicDiscussionMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionMember";
import type { IEconomicDiscussionMemberSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionMemberSession";

export async function test_api_member_session_ip_security_tracking(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Create member account for session security testing
  const memberCredentials = {
    username: RandomGenerator.name(2).toLowerCase().replace(/\s+/g, "_"),
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(10),
  } satisfies IEconomicDiscussionMember.ICreate;

  const member = await api.functional.auth.member.join(connection, {
    body: memberCredentials,
  });
  typia.assert(member);

  // Step 2: Initial login to establish baseline session
  const loginResponse = await api.functional.auth.member.login(connection, {
    body: {
      email: memberCredentials.email,
      password_hash: memberCredentials.password,
    } satisfies IEconomicDiscussionMember.ILogin,
  });
  typia.assert(loginResponse);

  // Step 3: Test session creation with IP security tracking
  // Simulate different network locations for security monitoring
  const deviceSessions: IEconomicDiscussionMemberSession[] = [];

  // Helper function to generate IPv4 format
  const generateIpv4 = () => {
    // Random IP in private ranges (192.168.x.x) for testing
    return `${Math.floor(Math.random() * 255) + 1}.${Math.floor(Math.random() * 255) + 1}.${Math.floor(Math.random() * 255) + 1}.${Math.floor(Math.random() * 255) + 1}` as string &
      tags.Format<"ipv4">;
  };

  await ArrayUtil.asyncRepeat(3, async (index) => {
    // Simulate different IP addresses representing different devices/networks
    const externalIpForSession = generateIpv4();
    const href = `https://discussion.example.com/login?device=browser_${index}`;
    const referrer = "https://google.com/search";

    // Create sessions from different network IPs
    const session =
      await api.functional.economicDiscussion.member.members.sessions.create(
        connection,
        {
          memberId: loginResponse.member.id,
          body: {
            href: href,
            referrer: referrer,
            ip: externalIpForSession,
          } satisfies IEconomicDiscussionMemberSession.ICreate,
        },
      );
    deviceSessions.push(session);
  });

  // Step 4: Verify session IP tracking works correctly
  TestValidator.equals(
    "first session member matches creator",
    deviceSessions[0].member.id,
    loginResponse.member.id,
  );
  TestValidator.equals(
    "first session member username matches expected profile",
    deviceSessions[0].member.username,
    loginResponse.member.username,
  );
  TestValidator.notEquals(
    "different sessions have different IP addresses",
    deviceSessions[0].ip,
    deviceSessions[1].ip,
  );
  TestValidator.predicate(
    "ip addresses follow IPv4 format pattern",
    deviceSessions.every((session) =>
      /^(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/.test(
        session.ip,
      ),
    ),
  );
  TestValidator.predicate(
    "sessions have href metadata",
    deviceSessions.every((session) => session.href.includes("browser_")),
  );
  TestValidator.predicate(
    "sessions track referrer",
    deviceSessions.every(
      (session) => session.referrer === "https://google.com/search",
    ),
  );
  TestValidator.predicate(
    "sessions track creation timestamp",
    deviceSessions.every(
      (session) => new Date(session.created_at).getTime() > 0,
    ),
  );
  TestValidator.predicate(
    "sessions contain member summary",
    deviceSessions.every(
      (session) => session.member.email === memberCredentials.email,
    ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEconomicDiscussionArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionArticle";
import type { IEconomicDiscussionAttachmentFileType } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionAttachmentFileType";
import type { IEconomicDiscussionAttachments } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionAttachments";
import type { IEconomicDiscussionCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionCategories";
import type { IEconomicDiscussionComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionComment";
import type { IEconomicDiscussionMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionMember";
import type { IEconomicDiscussionMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionMembers";
import type { IEconomicDiscussionModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionModerators";

/**
 * Test that unauthorized users cannot delete comments they don't own.
 *
 * Validates proper ownership validation and access control, ensuring that only
 * the comment author or moderators can perform deletion operations. Should
 * return appropriate error responses for unauthorized deletion attempts.
 *
 * Test flow:
 *
 * 1. Create original member account (comment owner)
 * 2. Create article as original member
 * 3. Add comment to article as original member
 * 4. Create second member account (unauthorized user)
 * 5. Attempt to delete comment as unauthorized user
 * 6. Verify deletion fails with appropriate error
 */
export async function test_api_comment_deletion_ownership_validation(
  connection: api.IConnection,
) {
  // Step 1: Create original member account (comment owner)
  const originalMember = await api.functional.auth.member.join(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(12),
    } satisfies IEconomicDiscussionMember.ICreate,
  });
  typia.assert(originalMember);

  // Step 2: Create article as original member
  const article =
    await api.functional.economicDiscussion.member.articles.create(connection, {
      body: {
        title: RandomGenerator.name(3),
        content: RandomGenerator.content({ paragraphs: 2 }),
        category_ids: [typia.random<string & tags.Format<"uuid">>()],
      } satisfies IEconomicDiscussionArticle.ICreate,
    });
  typia.assert(article);

  // Step 3: Add comment to article as original member
  const comment =
    await api.functional.economicDiscussion.member.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: {
          article_id: article.id,
          content: RandomGenerator.content({ paragraphs: 1 }),
        } satisfies IEconomicDiscussionComment.ICreate,
      },
    );
  typia.assert(comment);

  // Step 4: Create second member account (unauthorized user)
  const unauthorizedMember = await api.functional.auth.member.join(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(12),
    } satisfies IEconomicDiscussionMember.ICreate,
  });
  typia.assert(unauthorizedMember);

  // Step 5: Attempt to delete comment as unauthorized user
  await TestValidator.error(
    "unauthorized user should not delete other's comment",
    async () => {
      await api.functional.economicDiscussion.articles.comments.erase(
        connection,
        {
          articleId: article.id,
          commentId: comment.id,
        },
      );
    },
  );

  // Verify comment still exists by checking its properties
  TestValidator.equals(
    "comment should not be deleted",
    comment.deleted_at,
    undefined,
  );
  TestValidator.equals(
    "comment content preserved",
    comment.content !== undefined,
    true,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAttachmentFilename } from "@ORGANIZATION/PROJECT-api/lib/structures/IAttachmentFilename";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEconomicDiscussionArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionArticle";
import type { IEconomicDiscussionAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionAttachment";
import type { IEconomicDiscussionAttachmentFileType } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionAttachmentFileType";
import type { IEconomicDiscussionAttachments } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionAttachments";
import type { IEconomicDiscussionCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionCategories";
import type { IEconomicDiscussionMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionMember";
import type { IEconomicDiscussionMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionMembers";
import type { IEconomicDiscussionModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionModerators";
import type { IFileSize } from "@ORGANIZATION/PROJECT-api/lib/structures/IFileSize";
import type { IFileType } from "@ORGANIZATION/PROJECT-api/lib/structures/IFileType";
import type { IMimeType } from "@ORGANIZATION/PROJECT-api/lib/structures/IMimeType";
import type { IPageIEconomicDiscussionAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIEconomicDiscussionAttachment";

/**
 * Test pagination functionality for article attachments with comprehensive
 * validation of multi-page navigation, filtering, and metadata accuracy.
 *
 * This test validates the complete pagination workflow for article attachments
 * including:
 *
 * - Creation of sufficient attachments to test pagination (15+ attachments)
 * - Multi-page navigation with different page sizes (10-50 items per page)
 * - Page number validation starting from 1-based indexing
 * - File type filtering (image, document, spreadsheet) capabilities
 * - Pagination metadata accuracy (current page, total pages, total records)
 * - Cross-reference validation between created and retrieved data
 *
 * Steps:
 *
 * 1. Register a new member account for authentication
 * 2. Create an economic discussion article
 * 3. Generate 15+ file attachments to trigger pagination
 * 4. Test default pagination behavior (page 1, 10 items)
 * 5. Test custom pagination options (different page sizes, page numbers)
 * 6. Test file type filtering with pagination
 * 7. Validate pagination metadata accuracy
 * 8. Navigate to subsequent pages and verify data
 */
export async function test_api_attachments_pagination_navigation(
  connection: api.IConnection,
) {
  // Step 1: Create member account for authentication
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberAuth = await api.functional.auth.member.join(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: memberEmail,
      password: RandomGenerator.alphaNumeric(12),
    } satisfies IEconomicDiscussionMember.ICreate,
  });
  typia.assert(memberAuth);

  // Step 2: Create an economic discussion article
  const fileTypes: IEconomicDiscussionAttachmentFileType[] = [
    "image",
    "document",
    "spreadsheet",
  ];
  const categoryId = typia.random<string & tags.Format<"uuid">>();

  const member = memberAuth.member;
  const article =
    await api.functional.economicDiscussion.member.articles.create(connection, {
      body: {
        title: RandomGenerator.paragraph({ sentences: 3 }),
        content: RandomGenerator.content({
          paragraphs: 2,
          sentenceMin: 5,
          sentenceMax: 10,
        }),
        category_ids: [categoryId],
      } satisfies IEconomicDiscussionArticle.ICreate,
    });
  typia.assert(article);

  // Step 3: Create 15 attachments to test pagination
  const createdAttachments: IEconomicDiscussionAttachment[] = [];
  const fileSize = 1024; // 1KB
  const mimeTypes: IEconomicDiscussionAttachment.ICreate["mime_type"][] = [
    "image/jpeg",
    "image/png",
    "application/pdf",
    "application/msword",
    "application/vnd.ms-excel",
  ];

  await ArrayUtil.asyncRepeat(15, async (index) => {
    const fileType = fileTypes[index % 3];
    const mimeType = mimeTypes[index % 5];

    const attachment =
      await api.functional.economicDiscussion.member.articles.attachments.create(
        connection,
        {
          articleId: article.id,
          body: {
            filename: `test_file_${index}.${filenameExtension(fileType)}`,
            file_size: fileSize,
            file_type: fileType,
            mime_type: mimeType,
          } satisfies IEconomicDiscussionAttachment.ICreate,
        },
      );
    createdAttachments.push(attachment);
  });

  // Step 4: Test default pagination (page 1, 10 items)
  let firstPage =
    await api.functional.economicDiscussion.articles.attachments.index(
      connection,
      {
        articleId: article.id,
        body: {
          page: 1,
        } satisfies IEconomicDiscussionAttachment.IRequest,
      },
    );
  typia.assert(firstPage);

  TestValidator.equals("correct current page", firstPage.pagination.current, 1);
  TestValidator.equals(
    "items per page matches default",
    firstPage.pagination.limit,
    10,
  );
  TestValidator.equals(
    "total records matches created count",
    firstPage.pagination.records,
    15,
  );
  TestValidator.equals(
    "total pages calculated correctly",
    firstPage.pagination.pages,
    2,
  );
  TestValidator.predicate(
    "correct items count on first page",
    firstPage.data.length === 10,
  );

  // Step 5: Test second page
  let secondPage =
    await api.functional.economicDiscussion.articles.attachments.index(
      connection,
      {
        articleId: article.id,
        body: {
          page: 2,
        } satisfies IEconomicDiscussionAttachment.IRequest,
      },
    );
  typia.assert(secondPage);

  TestValidator.equals("second page current", secondPage.pagination.current, 2);
  TestValidator.equals("second page items count", secondPage.data.length, 5); // Remaining 5 items
  TestValidator.equals(
    "limit stays consistent",
    secondPage.pagination.limit,
    firstPage.pagination.limit,
  );

  // Step 6: Test custom page size
  const customPage =
    await api.functional.economicDiscussion.articles.attachments.index(
      connection,
      {
        articleId: article.id,
        body: {
          page: 1,
          limit: 15,
        } satisfies IEconomicDiscussionAttachment.IRequest,
      },
    );
  typia.assert(customPage);

  TestValidator.equals("custom limit applied", customPage.pagination.limit, 15);
  TestValidator.predicate(
    "all items on custom page",
    customPage.data.length === 15,
  );

  // Step 7: Test file type filtering with pagination
  const imageFilter =
    await api.functional.economicDiscussion.articles.attachments.index(
      connection,
      {
        articleId: article.id,
        body: {
          page: 1,
          file_type: "image",
        } satisfies IEconomicDiscussionAttachment.IRequest,
      },
    );
  typia.assert(imageFilter);

  TestValidator.predicate(
    "only image attachments returned",
    imageFilter.data.every(
      (a: IEconomicDiscussionAttachment.ISummary) => a.file_type === "image",
    ),
  );

  const documentFilter =
    await api.functional.economicDiscussion.articles.attachments.index(
      connection,
      {
        articleId: article.id,
        body: {
          page: 1,
          file_type: "document",
        } satisfies IEconomicDiscussionAttachment.IRequest,
      },
    );
  typia.assert(documentFilter);

  TestValidator.predicate(
    "only document attachments returned",
    documentFilter.data.every(
      (a: IEconomicDiscussionAttachment.ISummary) => a.file_type === "document",
    ),
  );

  // Helper function to get correct filename extensions
  function filenameExtension(
    fileType: IEconomicDiscussionAttachmentFileType,
  ): string {
    switch (fileType) {
      case "image":
        return "jpg";
      case "document":
        return "pdf";
      case "spreadsheet":
        return "xlsx";
      default:
        return "txt";
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEconomicDiscussionArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionArticle";
import type { IEconomicDiscussionAttachmentFileType } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionAttachmentFileType";
import type { IEconomicDiscussionAttachments } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionAttachments";
import type { IEconomicDiscussionCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionCategories";
import type { IEconomicDiscussionMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionMember";
import type { IEconomicDiscussionMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionMembers";
import type { IEconomicDiscussionModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionModerators";

/**
 * Test basic article creation by an authenticated member
 *
 * This test validates the complete workflow of economic discussion article
 * creation from member registration through article publication. The test
 * ensures that:
 *
 * - Members can successfully register with valid credentials
 * - Authenticated members can create articles with complete content
 * - Articles receive proper versioning starting at 1.0
 * - New articles enter the moderation queue with pending status
 * - Articles are correctly attributed to their creating member
 * - All content fields meet platform guidelines and requirements
 *
 * Business context: This test represents a core use case of the economic
 * discussion platform where members publish economic insights, political
 * analysis, and policy discussions. The creation process establishes
 * foundational metadata that supports the platform's moderation workflow and
 * content quality standards.
 */
export async function test_api_member_article_creation_basic(
  connection: api.IConnection,
) {
  // 1. Register as a new member to establish authentication context
  const memberCredentials = {
    username: RandomGenerator.name(1),
    email: typia.random<string & tags.Format<"email">>(),
    password: "SecurePassword123",
  } satisfies IEconomicDiscussionMember.ICreate;

  const member = await api.functional.auth.member.join(connection, {
    body: memberCredentials,
  });
  typia.assert(member);

  // 2. Validate member registration success
  TestValidator.equals(
    "member username matches registration",
    member.member.username,
    memberCredentials.username,
  );
  TestValidator.equals(
    "member email matches registration",
    member.member.email,
    memberCredentials.email,
  );
  TestValidator.predicate(
    "member has valid authentication token",
    member.access_token.length > 0,
  );

  // 3. Create a category for article organization
  const articleCategory: IEconomicDiscussionCategories.ISummary = {
    id: typia.random<string & tags.Format<"uuid">>() as any,
    code: "ECON_ANALYSIS",
    name: "Economic Analysis",
    article_count: 0,
    display_order: 1,
    is_active: true,
  };

  // 4. Create article with comprehensive content
  const articleData = {
    title: RandomGenerator.paragraph({ sentences: 3, wordMin: 4, wordMax: 8 }),
    content: RandomGenerator.content({
      paragraphs: 3,
      sentenceMin: 10,
      sentenceMax: 15,
      wordMin: 5,
      wordMax: 10,
    }),
    category_ids: [articleCategory.id],
  } satisfies IEconomicDiscussionArticle.ICreate;

  const article =
    await api.functional.economicDiscussion.member.articles.create(connection, {
      body: articleData,
    });
  typia.assert(article);

  // 5. Validate article creation results
  TestValidator.equals(
    "article title matches creation request",
    article.title,
    articleData.title,
  );
  TestValidator.equals(
    "article content matches creation request",
    article.content,
    articleData.content,
  );
  TestValidator.predicate(
    "article has valid UUID",
    article.id.length > 0 &&
      /^[a-zA-Z0-9_-]{8}-[a-zA-Z0-9_-]{4}-[a-zA-Z0-9_-]{4}-[a-zA-Z0-9_-]{4}-[a-zA-Z0-9_-]{12}$/.test(
        article.id,
      ),
  );

  // 6. Verify automatic version initialization
  TestValidator.equals(
    "article version initialized to 1.0",
    article.version,
    1,
  );

  // 7. Confirm pending moderation status assignment
  TestValidator.equals(
    "article status is pending moderation",
    article.status,
    "pending",
  );

  // 8. Validate view count initialization
  TestValidator.equals(
    "article view count initialized to zero",
    article.view_count,
    0,
  );

  // 9. Verify member author association
  TestValidator.equals(
    "article member author equals creating member",
    article.member_author,
    member.member.id,
  );

  // 10. Validate timestamp generation
  TestValidator.predicate(
    "article has valid creation timestamp",
    new Date(article.created_at).getTime() > Date.now() - 60000,
  ); // Created within last minute
  TestValidator.predicate(
    "article has valid update timestamp",
    new Date(article.updated_at).getTime() > Date.now() - 60000,
  ); // Updated within last minute
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEconomicDiscussionArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionArticle";
import type { IEconomicDiscussionAttachmentFileType } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionAttachmentFileType";
import type { IEconomicDiscussionAttachments } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionAttachments";
import type { IEconomicDiscussionCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionCategories";
import type { IEconomicDiscussionMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionMember";
import type { IEconomicDiscussionMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionMembers";
import type { IEconomicDiscussionModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionModerators";

/**
 * Test article creation with file attachments supporting economic analysis
 * discussions.
 *
 * This test validates the complete workflow for members to create economic
 * discussion articles with supporting file attachments. It covers:
 *
 * 1. Member registration and authentication setup
 * 2. Article creation with comprehensive content and metadata
 * 3. Multiple attachment types (images, documents, spreadsheets) supporting
 *    economic arguments
 * 4. Category assignment for content organization
 * 5. Validation of article structure and attachment relationships
 *
 * The test ensures members can upload various file types during article
 * creation to support their economic and political arguments with concrete data
 * and evidence.
 */
export async function test_api_article_creation_with_attachments(
  connection: api.IConnection,
) {
  // Step 1: Register as a new member to establish authentication
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberData = {
    username: RandomGenerator.name(),
    email: memberEmail,
    password: RandomGenerator.alphaNumeric(12),
  } satisfies IEconomicDiscussionMember.ICreate;

  const authorizedMember = await api.functional.auth.member.join(connection, {
    body: memberData,
  });
  typia.assert(authorizedMember);

  // Step 2: Generate diverse attachment types for economic analysis
  const imageAttachment = {
    file_size: typia.random<
      number & tags.Type<"int32"> & tags.Minimum<1000> & tags.Maximum<500000>
    >(),
    file_type: "image" as IEconomicDiscussionAttachmentFileType,
    filename: `economic_chart_${RandomGenerator.alphaNumeric(8)}.png`,
    mime_type: "image/png",
  } satisfies IEconomicDiscussionAttachments.ICreate;

  const documentAttachment = {
    file_size: typia.random<
      number & tags.Type<"int32"> & tags.Minimum<5000> & tags.Maximum<2000000>
    >(),
    file_type: "document" as IEconomicDiscussionAttachmentFileType,
    filename: `policy_analysis_${RandomGenerator.alphaNumeric(8)}.pdf`,
    mime_type: "application/pdf",
  } satisfies IEconomicDiscussionAttachments.ICreate;

  const spreadsheetAttachment = {
    file_size: typia.random<
      number & tags.Type<"int32"> & tags.Minimum<10000> & tags.Maximum<3000000>
    >(),
    file_type: "spreadsheet" as IEconomicDiscussionAttachmentFileType,
    filename: `economic_data_${RandomGenerator.alphaNumeric(8)}.xlsx`,
    mime_type:
      "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
  } satisfies IEconomicDiscussionAttachments.ICreate;

  // Step 3: Create article with comprehensive content and attachments
  const articleData = {
    title: RandomGenerator.name(4),
    content: RandomGenerator.content({
      paragraphs: 3,
      sentenceMin: 15,
      sentenceMax: 25,
      wordMin: 4,
      wordMax: 8,
    }),
    category_ids: ArrayUtil.repeat(2, () =>
      typia.random<string & tags.Format<"uuid">>(),
    ),
    attachments: [imageAttachment, documentAttachment, spreadsheetAttachment],
  } satisfies IEconomicDiscussionArticle.ICreate;

  const createdArticle =
    await api.functional.economicDiscussion.member.articles.create(connection, {
      body: articleData,
    });
  typia.assert(createdArticle);

  // Step 4: Validate article structure and relationships
  TestValidator.equals(
    "article title matches",
    createdArticle.title,
    articleData.title,
  );
  TestValidator.equals(
    "article content matches",
    createdArticle.content,
    articleData.content,
  );
  TestValidator.predicate(
    "article has positive view count",
    createdArticle.view_count >= 0,
  );
  TestValidator.equals("article version is 1.0", createdArticle.version, 1);
  TestValidator.equals(
    "article status is pending",
    createdArticle.status,
    "pending",
  );
  TestValidator.predicate(
    "article has created timestamp",
    createdArticle.created_at !== null,
  );
  TestValidator.predicate(
    "article has updated timestamp",
    createdArticle.updated_at !== null,
  );
  TestValidator.predicate(
    "categories are assigned",
    createdArticle.categories.length > 0,
  );

  // Step 5: Verify author attribution
  TestValidator.equals(
    "member author ID matches",
    createdArticle.member_author,
    authorizedMember.member.id,
  );
  TestValidator.equals(
    "member author profile matches",
    createdArticle.member_author_profile?.id,
    authorizedMember.member.id,
  );
  TestValidator.equals(
    "member author username matches",
    createdArticle.member_author_profile?.username,
    authorizedMember.member.username,
  );

  // Step 6: Validate attachment integration
  TestValidator.predicate(
    "attachments array exists",
    Array.isArray(articleData.attachments),
  );
  TestValidator.equals(
    "attachment count matches",
    articleData.attachments?.length,
    3,
  );

  // Validate each attachment type
  articleData.attachments?.forEach((attachment, index) => {
    TestValidator.predicate(
      `attachment ${index} has valid file size`,
      attachment.file_size > 0,
    );
    TestValidator.predicate(
      `attachment ${index} has valid filename`,
      attachment.filename.length > 0,
    );
    TestValidator.predicate(
      `attachment ${index} has valid MIME type`,
      attachment.mime_type.length > 0,
    );
    TestValidator.predicate(
      `attachment ${index} has recognized file type`,
      ["image", "document", "spreadsheet"].includes(attachment.file_type),
    );
  });

  // Step 7: Test attachment size limits (edge case validation)
  const maxSizeAttachment = {
    file_size: 10485760, // 10MB maximum
    file_type: "document" as IEconomicDiscussionAttachmentFileType,
    filename: "large_economic_report.pdf",
    mime_type: "application/pdf",
  } satisfies IEconomicDiscussionAttachments.ICreate;

  const articleWithLargeAttachment = {
    title: "Economic Analysis with Large Dataset",
    content: RandomGenerator.content({
      paragraphs: 2,
      sentenceMin: 10,
      sentenceMax: 20,
    }),
    category_ids: [typia.random<string & tags.Format<"uuid">>()],
    attachments: [maxSizeAttachment],
