      },
    );
  typia.assert(initialCategory);

  // Validate immediate category creation and properties
  TestValidator.equals(
    "category code is unique and url-safe",
    initialCategory.code,
    categoryCode.slice(0, 50),
  );
  TestValidator.predicate(
    "category displays correct name",
    initialCategory.name === "Economic Policy Analysis",
  );
  TestValidator.predicate(
    "category is active immediately",
    initialCategory.is_active === true,
  );
  TestValidator.predicate(
    "category displays at position 1",
    initialCategory.display_order === 1,
  );

  // Step 3: Create additional categories to test display ordering and uniqueness
  const secondCategory =
    await api.functional.economicDiscussion.moderator.categories.create(
      connection,
      {
        body: {
          code: "market_analysis_zone",
          name: "Market Trends & Forecasting",
          description:
            "Market insights, economic indicators, and financial trend analysis for informed investment decisions",
          display_order: 2,
          is_active: true,
        } satisfies IEconomicDiscussionCategory.ICreate,
      },
    );
  typia.assert(secondCategory);

  const thirdCategory =
    await api.functional.economicDiscussion.moderator.categories.create(
      connection,
      {
        body: {
          code: "international_trade",
          name: "Global Trade Relations",
          display_order: 3,
          is_active: false, // Inactive category for testing
        } satisfies IEconomicDiscussionCategory.ICreate,
      },
    );
  typia.assert(thirdCategory);

  // Validate category relationships and properties
  TestValidator.predicate(
    "third category is inactive as configured",
    thirdCategory.is_active === false,
  );
  TestValidator.predicate(
    "categories maintain unique codes",
    initialCategory.code !== secondCategory.code &&
      secondCategory.code !== thirdCategory.code,
  );
  TestValidator.predicate(
    "display order follows sequential configuration",
    initialCategory.display_order < secondCategory.display_order &&
      secondCategory.display_order < thirdCategory.display_order,
  );

  // Step 4: Test category content readiness
  const allCategories = [initialCategory, secondCategory, thirdCategory];
  const activeCategories = allCategories.filter((cat) => cat.is_active);

  // Validate categories for immediate article assignment capability
  activeCategories.forEach((activeCat) => {
    TestValidator.predicate(
      `active category ${activeCat.name} allows article assignment`,
      activeCat.is_active === true && activeCat.code.length >= 1,
    );
  });

  // Validate platform taxonomy expansion and discoverability
  TestValidator.equals("total active categories", activeCategories.length, 2);
  TestValidator.predicate(
    "all categories have valid unique identifiers",
    initialCategory.id !== secondCategory.id &&
      secondCategory.id !== thirdCategory.id,
  );

  // Final validation: Complete workflow integration test
  const completeWorkflowSuccess = allCategories.every(
    (category) =>
      category.code.length >= 1 &&
      category.name.length >= 1 &&
      category.display_order >= 0 &&
      typeof category.is_active === "boolean",
  );
  TestValidator.predicate(
    "all categories satisfy platform taxonomy standards",
    completeWorkflowSuccess,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEconomicDiscussionCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionCategory";
import type { IEconomicDiscussionModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionModerator";

/**
 * Test category creation validation including code uniqueness and display
 * ordering constraints. This E2E test validates that the system enforces unique
 * category codes for URL generation and maintains proper display ordering for
 * navigation hierarchy in economic/political discussion board categorization.
 *
 * 1. Register and authenticate as moderator to gain management permissions
 * 2. Create initial test category with unique code and display order
 * 3. Attempt duplicate category code creation to validate uniqueness enforcement
 * 4. Create additional categories with various display_order values (0, 1, 2, 3,
 *    4, 100)
 * 5. Test both active and inactive category creation for complete coverage
 * 6. Verify all created categories maintain correct properties and relationships
 */
export async function test_api_category_validation_and_uniqueness(
  connection: api.IConnection,
) {
  // Step 1: Register and authenticate moderator for category management
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: moderatorEmail,
      password_hash: RandomGenerator.alphaNumeric(32),
      moderation_level: "admin",
    } satisfies IEconomicDiscussionModerator.ICreate,
  });
  typia.assert(moderator);

  // Step 2: Create initial category for uniqueness testing
  const firstCategory =
    await api.functional.economicDiscussion.moderator.categories.create(
      connection,
      {
        body: {
          code: "economics",
          name: "Economics",
          description: "Discussions about economic theory and policy",
          display_order: 1,
          is_active: true,
        } satisfies IEconomicDiscussionCategory.ICreate,
      },
    );
  typia.assert(firstCategory);

  // Step 3: Validate category code uniqueness by attempting duplicate
  await TestValidator.error(
    "duplicate category code should be rejected",
    async () => {
      await api.functional.economicDiscussion.moderator.categories.create(
        connection,
        {
          body: {
            code: "economics", // Same as first category - must fail
            name: "Duplicate Economics",
            description: "Another economics category with same code",
            display_order: 2,
            is_active: true,
          } satisfies IEconomicDiscussionCategory.ICreate,
        },
      );
    },
  );

