import { IEconomicDiscussionRecentlyViewed } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionRecentlyViewed";
import { IEconomicDiscussionSortOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionSortOrder";
import { IPageIEconomicDiscussionArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIEconomicDiscussionArticle";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { ICrIPageIntegerRequired } from "@ORGANIZATION/PROJECT-api/lib/structures/ICrIPageIntegerRequired";
import { IEconomicDiscussionArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionArticle";
import { IEconomicDiscussionMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionMembers";
import { IEconomicDiscussionModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionModerators";
import { IEconomicDiscussionCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionCategories";
import { MemberPayload } from "../decorators/payload/MemberPayload";

export async function patchEconomicDiscussionMemberDiscoveryRecentlyViewed(props: {
  member: MemberPayload;
  body: IEconomicDiscussionRecentlyViewed.IRequest;
}): Promise<IPageIEconomicDiscussionArticle.ISummary> {
  const page = props.body.page;
  const limit = props.body.limit;
  const skip = (page - 1) * limit;

  // Since there's no explicit recently viewed table, we'll use the member's interaction history
  // Query articles based on search history or articles the member has interacted with
  const searchHistory =
    await MyGlobal.prisma.economic_discussion_search_history.findMany({
      where: {
        economic_discussion_member_id: props.member.id,
      },
      orderBy: {
        created_at: "desc",
      },
      take: 100, // Get recent search history
    });

  // Get unique article IDs from search queries (extracting potential article references)
  const potentialArticleIds = searchHistory
    .map((sh) => {
      // Try to extract potential article IDs from search queries
      const matches = sh.query_text.match(
        /[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi,
      );
      return matches || [];
    })
    .flat()
    .filter((id, index, arr) => arr.indexOf(id) === index); // Remove duplicates

  // If no potential articles from search, get member's own recent articles as fallback
  let articleIds =
    potentialArticleIds.length > 0
      ? potentialArticleIds
      : (
          await MyGlobal.prisma.economic_discussion_articles.findMany({
            where: {
              economic_discussion_member_id: props.member.id,
            },
            orderBy: {
              created_at: "desc",
            },
            take: 50,
            select: {
              id: true,
            },
          })
        ).map((a) => a.id);

  // Apply date filtering if provided
  if (props.body.date_from || props.body.date_to) {
    const dateFilteredArticles =
      await MyGlobal.prisma.economic_discussion_articles.findMany({
        where: {
          id: { in: articleIds },
          ...(props.body.date_from && {
            created_at: { gte: props.body.date_from },
          }),
          ...(props.body.date_to && {
            created_at: { lte: props.body.date_to },
          }),
        },
        select: { id: true },
      });
    articleIds = dateFilteredArticles.map((a) => a.id);
  }

  // Apply deletion filtering
  const deletionFilter = props.body.include_deleted ? {} : { deleted_at: null };

  // Get total count and paginated articles
  const [articles, total] = await Promise.all([
    MyGlobal.prisma.economic_discussion_articles.findMany({
      where: {
        id: { in: articleIds },
        ...deletionFilter,
      },
      skip,
      take: limit,
      orderBy: {
        updated_at: props.body.sort_order === "asc" ? "asc" : "desc",
      },
      include: {
        member: true,
        moderator: true,
        economic_discussion_article_categories: {
          include: {
            category: true,
          },
        },
      },
    }),
    MyGlobal.prisma.economic_discussion_articles.count({
      where: {
        id: { in: articleIds },
        ...deletionFilter,
      },
    }),
  ]);

  // Calculate attachment and comment counts for all articles
  const [attachmentCounts, commentCounts] = await Promise.all([
    MyGlobal.prisma.economic_discussion_attachments.groupBy({
      by: ["economic_discussion_article_id"],
      where: {
        economic_discussion_article_id: { in: articles.map((a) => a.id) },
      },
      _count: {
        economic_discussion_article_id: true,
      },
    }),
    MyGlobal.prisma.economic_discussion_comments.groupBy({
      by: ["economic_discussion_article_id"],
      where: {
        economic_discussion_article_id: { in: articles.map((a) => a.id) },
      },
      _count: {
        economic_discussion_article_id: true,
      },
    }),
  ]);

  // Create lookup maps
  const attachmentMap = new Map(
    attachmentCounts.map((ac) => [
      ac.economic_discussion_article_id,
      ac._count.economic_discussion_article_id,
    ]),
  );
  const commentMap = new Map(
    commentCounts.map((cc) => [
      cc.economic_discussion_article_id,
      cc._count.economic_discussion_article_id,
    ]),
  );

  // Transform to summary format
  const data = articles.map((article) => {
    const memberAuthor = article.member
      ? {
          id: article.member.id,
          username: article.member.username,
          email_verified: article.member.email_verified,
          reputation_score: article.member.reputation_score,
          created_at: toISOStringSafe(article.member.created_at),
        }
      : undefined;

    const moderatorAuthor = article.moderator
      ? {
          id: article.moderator.id,
          username: article.moderator.username,
          moderation_level: article.moderator.moderation_level as
            | "standard"
            | "senior"
            | "admin",
          created_at: toISOStringSafe(article.moderator.created_at),
        }
      : undefined;

    const categories = article.economic_discussion_article_categories.map(
      (ac) => ({
        id: ac.category.id,
        code: ac.category.code,
        name: ac.category.name,
        display_order: ac.category.display_order,
        is_active: ac.category.is_active,
        article_count: ac.category.article_count,
      }),
    );

    return {
      id: article.id,
      title: article.title,
      view_count: article.view_count,
      created_at: toISOStringSafe(article.created_at),
      updated_at: toISOStringSafe(article.updated_at),
      economic_discussion_member_id: article.economic_discussion_member_id!,
      economic_discussion_moderator_id:
        article.economic_discussion_moderator_id!,
      member_author: memberAuthor,
      moderator_author: moderatorAuthor,
      categories,
      attachments_count: attachmentMap.get(article.id) || 0,
      comments_count: commentMap.get(article.id) || 0,
      status: article.status as "pending" | "approved" | "rejected",
    };
  });

  return {
    data,
    pagination: {
      current: page.toString(),
      limit: limit.toString(),
      records: total.toString(),
      pages: Math.ceil(total / limit).toString(),
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IEconomicDiscussionRecommendationsRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionRecommendationsRequest";
import { IEconomicDiscussionRecommendationsList } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionRecommendationsList";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { ICrIPageIntegerRequired } from "@ORGANIZATION/PROJECT-api/lib/structures/ICrIPageIntegerRequired";
import { IEconomicDiscussionRecommendation } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionRecommendation";
import { IEconomicDiscussionCategorySummary } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionCategorySummary";

export async function patchEconomicDiscussionModeratorDiscoveryRecommendations(props: {
  body: IEconomicDiscussionRecommendationsRequest;
}): Promise<IEconomicDiscussionRecommendationsList> {
  const maxResults = props.body.maxResults ?? 10;
  const minRelevanceScore = props.body.minRelevanceScore ?? 0.1;

  if (maxResults < 1 || maxResults > 50) {
    throw new HttpException("maxResults must be between 1 and 50", 400);
  }

  // Validate category IDs if provided
  if (props.body.categoryIds && props.body.categoryIds.length > 0) {
    const validCategories =
      await MyGlobal.prisma.economic_discussion_categories.count({
        where: {
          id: { in: props.body.categoryIds },
          is_active: true,
          deleted_at: null,
        },
      });

    if (validCategories !== props.body.categoryIds.length) {
      throw new HttpException(
        "One or more category IDs are invalid or inactive",
        400,
      );
    }
  }

  // Build base query conditions
  const whereConditions: Prisma.economic_discussion_articlesWhereInput = {
    status: "approved",
    deleted_at: null,
  };

  // Add category filtering if provided
  if (props.body.categoryIds && props.body.categoryIds.length > 0) {
    whereConditions.economic_discussion_article_categories = {
      some: {
        economic_discussion_category_id: {
          in: props.body.categoryIds,
        },
      },
    };
  }

  // Filter out articles from interaction history
  if (
    props.body.interactionHistory &&
    props.body.interactionHistory.length > 0
  ) {
    whereConditions.id = {
      notIn: props.body.interactionHistory,
    };
  }

  // Get articles with comprehensive relationships
  const articles = await MyGlobal.prisma.economic_discussion_articles.findMany({
    where: whereConditions,
    include: {
      economic_discussion_article_categories: {
        include: {
          category: true,
        },
      },
      economic_discussion_comments: {
        where: {
          status: "approved",
          deleted_at: null,
        },
      },
    },
    orderBy: {
      created_at: "desc",
    },
    take: Math.max(maxResults * 3, 100), // Get sufficient candidates for relevance filtering
  });

  // Calculate relevance scores
  const scoredRecommendations: IEconomicDiscussionRecommendation[] = articles
    .map((article) => {
      let relevanceScore = 0;
      let factors: string[] = [];

      // Category alignment score (0-0.4)
      if (props.body.categoryIds && props.body.categoryIds.length > 0) {
        const articleCategories =
          article.economic_discussion_article_categories.map(
            (ac: any) => ac.category.id,
          );
        const categoryOverlap = articleCategories.filter((id: string) =>
          props.body.categoryIds!.includes(id),
        ).length;
        const categoryScore =
          (categoryOverlap / props.body.categoryIds!.length) * 0.4;
        relevanceScore += categoryScore;
        if (categoryScore > 0) {
          factors.push("category alignment");
        }
      }

      // Keyword relevance score (0-0.3) - using better text analysis
      if (props.body.searchKeywords && props.body.searchKeywords.length > 0) {
        const content = (article.title + " " + article.content).toLowerCase();
        let totalKeywordScore = 0;
        let matchedKeywords = 0;

        props.body.searchKeywords.forEach((keyword) => {
          const keywordLower = keyword.toLowerCase();
          const titleMatches =
            (article.title.toLowerCase().split(keywordLower).length - 1) * 2; // Title matches weighted higher
          const contentMatches = content.split(keywordLower).length - 1;
          const keywordRelevance =
            Math.min(titleMatches + contentMatches, 3) / 3; // Cap at 3 matches

          if (keywordRelevance > 0) {
            totalKeywordScore += keywordRelevance;
            matchedKeywords++;
          }
        });

        const keywordScore =
          (totalKeywordScore / Math.max(props.body.searchKeywords.length, 1)) *
          0.3;
        relevanceScore += keywordScore;
        if (matchedKeywords > 0) {
          factors.push(
            `${matchedKeywords} keyword${matchedKeywords > 1 ? "s" : ""} matched`,
          );
        }
      }

      // Engagement score (0-0.2)
      const engagementScore = Math.min(
        (article.view_count / 1000) * 0.1 +
          (article.economic_discussion_comments.length / 50) * 0.1,
        0.2,
      );
      relevanceScore += engagementScore;
      if (engagementScore > 0.1) {
        factors.push("high community engagement");
      }

      // Recency score (0-0.1)
      const daysSinceCreation =
        (new Date().getTime() - new Date(article.created_at).getTime()) /
        (1000 * 60 * 60 * 24);
      const recencyScore = Math.max(0, (30 - daysSinceCreation) / 30) * 0.1;
      relevanceScore += recencyScore;
      if (recencyScore > 0.05) {
        factors.push("recently published");
      }

      // Consistency score boost for quality content
      if (
        article.economic_discussion_article_categories.length >= 2 &&
        article.economic_discussion_comments.length >= 3 &&
        article.view_count >= 50
      ) {
        relevanceScore += 0.05;
        factors.push("quality content indicators");
      }

      // Determine author name using member/moderator IDs
      const authorName =
        article.economic_discussion_member_id ||
        article.economic_discussion_moderator_id ||
        "Community Contributor";

      let recommendationReason = "Recommended based on";
      if (factors.length > 0) {
        recommendationReason += " " + factors.slice(0, 2).join(" and ");
      } else {
        recommendationReason += " trending economic discussions";
      }

      return {
        id: article.id,
        title: article.title,
        content:
          article.content.substring(0, 500) +
          (article.content.length > 500 ? "..." : ""),
        authorName,
        categoryCount: article.economic_discussion_article_categories.length,
        viewCount: article.view_count,
        commentCount: article.economic_discussion_comments.length,
        relevanceScore: Math.round(relevanceScore * 100) / 100,
        recommendationReason,
        categories: article.economic_discussion_article_categories.map(
          (ac: any) => ({
            id: ac.category.id,
            code: ac.category.code,
            name: ac.category.name,
            displayOrder: ac.category.display_order,
            isActive: ac.category.is_active,
            articleCount: ac.category.article_count,
          }),
        ),
        createdAt: toISOStringSafe(article.created_at),
        updatedAt: toISOStringSafe(article.updated_at),
        version: article.version,
        status: article.status,
      };
    })
    .filter((rec) => rec.relevanceScore >= minRelevanceScore)
    .sort((a, b) => b.relevanceScore - a.relevanceScore)
    .slice(0, maxResults);

  // Build pagination metadata
  const totalRecords = scoredRecommendations.length;
  const pages = Math.ceil(totalRecords / maxResults);

  return {
    data: scoredRecommendations,
    pagination: {
      current: "1" as ICrIPageIntegerRequired,
      limit: maxResults.toString() as ICrIPageIntegerRequired,
      records: totalRecords.toString() as ICrIPageIntegerRequired,
      pages: pages.toString() as ICrIPageIntegerRequired,
    },
  };
}

