import { IEconomicDiscussionArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionArticle";
import { IPageIEconomicDiscussionArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIEconomicDiscussionArticle";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { ICrIPageIntegerRequired } from "@ORGANIZATION/PROJECT-api/lib/structures/ICrIPageIntegerRequired";
import { IEconomicDiscussionMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionMembers";
import { IEconomicDiscussionModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionModerators";
import { IEconomicDiscussionCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionCategories";

export async function patchEconomicDiscussionSearchArticles(props: {
  body: IEconomicDiscussionArticle.IRequest;
}): Promise<IPageIEconomicDiscussionArticle.ISummary> {
  // Extract pagination parameters
  const page = props.body.page;
  const limit = props.body.limit;
  const skip = (page - 1) * limit;

  // Build comprehensive WHERE conditions
  const whereConditions: any = {};

  // Status filtering
  if (props.body.status !== undefined && props.body.status !== null) {
    whereConditions.status = props.body.status;
  }

  // Author filtering - articles can have either member or moderator author
  if (props.body.author !== undefined && props.body.author !== null) {
    whereConditions.OR = [
      { economic_discussion_member_id: props.body.author },
      { economic_discussion_moderator_id: props.body.author },
    ];
  }

  // Date range filtering
  if (
    props.body.created_after !== undefined &&
    props.body.created_after !== null
  ) {
    whereConditions.created_at = {
      ...whereConditions.created_at,
      gte: props.body.created_after,
    };
  }
  if (
    props.body.created_before !== undefined &&
    props.body.created_before !== null
  ) {
    whereConditions.created_at = {
      ...whereConditions.created_at,
      lte: props.body.created_before,
    };
  }

  // View count range filtering
  if (
    props.body.view_count_min !== undefined &&
    props.body.view_count_min !== null
  ) {
    whereConditions.view_count = {
      ...whereConditions.view_count,
      gte: props.body.view_count_min,
    };
  }
  if (
    props.body.view_count_max !== undefined &&
    props.body.view_count_max !== null
  ) {
    whereConditions.view_count = {
      ...whereConditions.view_count,
      lte: props.body.view_count_max,
    };
  }

  // Full-text search using PostgreSQL operators
  if (props.body.search !== undefined && props.body.search !== null) {
    // Use PostgreSQL full-text search for better performance
    whereConditions.AND = [
      ...(whereConditions.AND || []),
      {
        OR: [
          { title: { search: props.body.search } },
          { content: { search: props.body.search } },
        ],
      },
    ];
  }

  // Category filtering through junction table
  if (
    props.body.categories_code !== undefined &&
    props.body.categories_code !== null &&
    props.body.categories_code.length > 0
  ) {
    // Get category IDs for the codes
    const categories =
      await MyGlobal.prisma.economic_discussion_categories.findMany({
        where: { code: { in: props.body.categories_code } },
      });

    if (categories.length > 0) {
      const categoryIds = categories.map((c) => c.id);
      whereConditions.economic_discussion_article_categories = {
        some: {
          economic_discussion_category_id: { in: categoryIds },
        },
      };
    }
  }

  // Define sorting logic
  let orderBy: any = { created_at: "desc" }; // Default sort
  if (props.body.sort_by !== undefined && props.body.sort_by !== null) {
    const sortOrder = props.body.sort_order === "asc" ? "asc" : "desc";
    switch (props.body.sort_by) {
      case "created_at":
        orderBy = { created_at: sortOrder };
        break;
      case "view_count":
        orderBy = { view_count: sortOrder };
        break;
      case "title":
        orderBy = { title: sortOrder };
        break;
      default: // relevance (or default)
        orderBy = { created_at: "desc" }; // Fallback to creation date for relevance
        break;
    }
  }

  // Execute main query and total count in parallel
  const [articles, totalCount] = await Promise.all([
    MyGlobal.prisma.economic_discussion_articles.findMany({
      where: whereConditions,
      skip,
      take: limit,
      orderBy,
      include: {
        economic_discussion_article_categories: {
          include: {
            category: true,
          },
        },
        economic_discussion_attachments: {
          select: { id: true },
        },
        economic_discussion_comments: {
          select: { id: true },
        },
      },
    }),
    MyGlobal.prisma.economic_discussion_articles.count({
      where: whereConditions,
    }),
  ]);

  // Build proper pagination metadata
  const pagination: IPage.IPagination = {
    current: page.toString() as string & tags.Format<"uuid">,
    limit: limit.toString() as string & tags.Format<"uuid">,
    records: totalCount.toString() as string & tags.Format<"uuid">,
    pages: Math.ceil(totalCount / limit).toString() as string &
      tags.Format<"uuid">,
  };

  return {
    data: await Promise.all(
      articles.map(async (article) => {
        // Get member author separately
        let memberAuthor = undefined;
        if (article.economic_discussion_member_id) {
          memberAuthor =
            await MyGlobal.prisma.economic_discussion_members.findUnique({
              where: { id: article.economic_discussion_member_id },
            });
        }

        // Get moderator author separately
        let moderatorAuthor = undefined;
        if (article.economic_discussion_moderator_id) {
          moderatorAuthor =
            await MyGlobal.prisma.economic_discussion_moderators.findUnique({
              where: { id: article.economic_discussion_moderator_id },
            });
        }

        return {
          id: article.id,
          title: article.title,
          view_count: article.view_count,
          created_at: toISOStringSafe(article.created_at),
          updated_at: toISOStringSafe(article.updated_at),
          economic_discussion_member_id:
            article.economic_discussion_member_id ?? "",
          economic_discussion_moderator_id:
            article.economic_discussion_moderator_id ?? "",
          member_author: memberAuthor
            ? {
                id: memberAuthor.id,
                username: memberAuthor.username,
                email_verified: memberAuthor.email_verified,
                reputation_score: memberAuthor.reputation_score,
                created_at: toISOStringSafe(memberAuthor.created_at),
              }
            : undefined,
          moderator_author: moderatorAuthor
            ? {
                id: moderatorAuthor.id,
                username: moderatorAuthor.username,
                moderation_level: moderatorAuthor.moderation_level as
                  | "standard"
                  | "senior"
                  | "admin",
                created_at: toISOStringSafe(moderatorAuthor.created_at),
              }
            : undefined,
          categories: (
            (article as any).economic_discussion_article_categories || []
          ).map((ac: any) => ({
            id: ac.category.id,
            code: ac.category.code,
            name: ac.category.name,
            display_order: ac.category.display_order,
            is_active: ac.category.is_active,
            article_count: ac.category.article_count,
          })),
          attachments_count: (
            (article as any).economic_discussion_attachments || []
          ).length,
          comments_count: ((article as any).economic_discussion_comments || [])
            .length,
          status: article.status as "pending" | "approved" | "rejected",
        };
      }),
    ),
    pagination,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IEconomicDiscussionMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionMember";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthMemberLogin(props: {
  body: IEconomicDiscussionMember.ILogin;
}): Promise<IEconomicDiscussionMember.IAuthorized> {
  // Find member by email for authentication
  const member = await MyGlobal.prisma.economic_discussion_members.findFirst({
    where: { email: props.body.email },
  });

  if (!member) {
    throw new HttpException("Invalid credentials", 401);
  }

  // Verify password using PasswordUtil
  const isValid = await PasswordUtil.verify(
    props.body.password_hash,
    member.password_hash,
  );

  if (!isValid) {
    throw new HttpException("Invalid credentials", 401);
  }

  // Check if email is verified
  if (!member.email_verified) {
    throw new HttpException("Please verify your email first", 403);
  }

  // Create new session for this login
  const now = new Date();
  const accessExpires = new Date(now.getTime() + 30 * 60 * 1000); // 30 minutes
  const refreshExpires = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000); // 7 days

  const session =
    await MyGlobal.prisma.economic_discussion_member_sessions.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        economic_discussion_member_id: member.id,
        // Add required properties that were missing
        ip: "0.0.0.0",
        href: "/",
        created_at: now,
        expired_at: accessExpires,
      },
    });

  // Generate JWT tokens with proper payload structure
  const tokenPayload = {
    type: "member" as const,
    id: member.id,
    session_id: session.id,
    created_at: toISOStringSafe(now),
  };

  const accessToken = jwt.sign(tokenPayload, MyGlobal.env.JWT_SECRET_KEY, {
    expiresIn: "30m",
    issuer: "autobe",
  });

  const refreshTokenPayload = {
    ...tokenPayload,
    tokenType: "refresh" as const,
  };

  const refreshToken = jwt.sign(
    refreshTokenPayload,
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  // Calculate expiration time in seconds
  const expiresInSeconds = Math.floor(
    (accessExpires.getTime() - now.getTime()) / 1000,
  );

  // Return authorized member response
  return {
    member: {
      id: member.id,
      username: member.username,
      email: member.email,
    },
    access_token: accessToken,
    refresh_token: refreshToken,
    expires_in: expiresInSeconds as number & tags.Type<"int32">,
    token: {
      access: accessToken,
      refresh: refreshToken,
      expired_at: toISOStringSafe(session.expired_at ?? accessExpires),
      refreshable_until: toISOStringSafe(refreshExpires),
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IEconomicDiscussionRecommendationsRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionRecommendationsRequest";
import { IEconomicDiscussionRecommendationsList } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionRecommendationsList";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { ICrIPageIntegerRequired } from "@ORGANIZATION/PROJECT-api/lib/structures/ICrIPageIntegerRequired";
import { IEconomicDiscussionRecommendation } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionRecommendation";
import { IEconomicDiscussionCategorySummary } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionCategorySummary";

export async function patchEconomicDiscussionMemberDiscoveryRecommendations(props: {
  body: IEconomicDiscussionRecommendationsRequest;
}): Promise<IEconomicDiscussionRecommendationsList> {
  // Extract request parameters with defaults
  const {
    categoryIds,
    searchKeywords,
    interactionHistory,
    maxResults = 10,
    minRelevanceScore = 0.1,
  } = props.body;

  // Validate maxResults constraint
  if (maxResults > 50 || maxResults < 1) {
    throw new HttpException("maxResults must be between 1 and 50", 400);
  }

  // Build article query with optional category filtering
  const articleWhere: Record<string, unknown> = {
    deleted_at: null,
    status: "approved",
  };

  // Get base articles, filtered by categories if specified
  let articles;
  if (categoryIds && categoryIds.length > 0) {
    // Find articles that are in the specified categories
    const articleCategories =
      await MyGlobal.prisma.economic_discussion_article_categories.findMany({
        where: {
          economic_discussion_category_id: { in: categoryIds },
        },
        select: { economic_discussion_article_id: true },
      });

    const articleIdsInCategories = articleCategories.map(
      (ac) => ac.economic_discussion_article_id,
    );

    articles = await MyGlobal.prisma.economic_discussion_articles.findMany({
      where: {
        ...articleWhere,
        id: { in: articleIdsInCategories },
      },
      take: maxResults * 2,
      orderBy: [{ view_count: "desc" }, { created_at: "desc" }],
      include: {
        member: {
          select: {
            username: true,
          },
        },
        moderator: {
          select: {
            username: true,
          },
        },
      },
    });
  } else {
    articles = await MyGlobal.prisma.economic_discussion_articles.findMany({
      where: articleWhere,
      take: maxResults * 2,
      orderBy: [{ view_count: "desc" }, { created_at: "desc" }],
      include: {
        member: {
          select: {
            username: true,
          },
        },
        moderator: {
          select: {
            username: true,
          },
        },
      },
    });
  }

  // Get comment counts for articles
  const articleIds = articles.map((article) => article.id);
  const commentCounts =
    articleIds.length > 0
      ? await MyGlobal.prisma.economic_discussion_comments.groupBy({
          by: ["economic_discussion_article_id"],
          where: {
            economic_discussion_article_id: { in: articleIds },
            deleted_at: null,
            status: "approved",
          },
          _count: {
            id: true,
          },
        })
      : [];

  // Create comment count map
  const commentCountMap = new Map(
    commentCounts.map((count) => [
      count.economic_discussion_article_id,
      count._count.id,
    ]),
  );

  // Get category information for articles
  const articleCategoryMap = new Map<
    string,
    IEconomicDiscussionCategorySummary[]
  >();
  if (articleIds.length > 0) {
    const articleCategories =
      await MyGlobal.prisma.economic_discussion_article_categories.findMany({
        where: {
          economic_discussion_article_id: { in: articleIds },
        },
      });

    // Fetch category details separately
    const categoryIds = articleCategories.map(
      (ac) => ac.economic_discussion_category_id,
    );
    const categories =
      categoryIds.length > 0
        ? await MyGlobal.prisma.economic_discussion_categories.findMany({
            where: {
              id: { in: categoryIds },
            },
            select: {
              id: true,
              code: true,
              name: true,
              display_order: true,
              is_active: true,
              article_count: true,
            },
          })
        : [];

    const categoryMap = new Map(
      categories.map((category) => [category.id, category]),
    );

    // Group categories by article
    for (const ac of articleCategories) {
      const category = categoryMap.get(ac.economic_discussion_category_id);
      if (category) {
        const categories =
          articleCategoryMap.get(ac.economic_discussion_article_id) || [];
        categories.push({
          id: category.id as string & tags.Format<"uuid">,
          code: category.code,
          name: category.name,
          displayOrder: category.display_order as number &
            tags.Type<"int32"> &
            tags.Minimum<0> &
            tags.Maximum<999>,
          isActive: category.is_active,
          articleCount: category.article_count as number &
            tags.Type<"int32"> &
            tags.Minimum<0> &
            tags.Maximum<100000>,
        });
        articleCategoryMap.set(ac.economic_discussion_article_id, categories);
      }
    }
  }

  // Calculate relevance scores and build recommendations
  const recommendations: IEconomicDiscussionRecommendation[] = [];

  for (const article of articles) {
    // Calculate base relevance score based on multiple factors
    let relevanceScore = 0.5; // Base score

    // Boost based on view count (normalize to 0-0.3 range)
    const viewBoost = Math.min(article.view_count / 1000, 0.3);
    relevanceScore += viewBoost;

    // Boost based on recency (0-0.2 range)
    const now = new Date();
    const articleAge = now.getTime() - article.created_at.getTime();
    const daysOld = articleAge / (1000 * 60 * 60 * 24);
    const recencyBoost = Math.max(0, 0.2 - (daysOld / 30) * 0.2);
    relevanceScore += recencyBoost;

    // Boost based on search keywords if provided
    if (searchKeywords && searchKeywords.length > 0) {
      const titleMatch = searchKeywords.some((keyword) =>
        article.title.toLowerCase().includes(keyword.toLowerCase()),
      );
      const contentMatch = searchKeywords.some((keyword) =>
        article.content.toLowerCase().includes(keyword.toLowerCase()),
      );

      if (titleMatch) relevanceScore += 0.1;
      if (contentMatch) relevanceScore += 0.05;
    }

    // Penalize articles already in interaction history
    if (interactionHistory && interactionHistory.includes(article.id)) {
      relevanceScore *= 0.7; // Reduce score by 30%
    }

    // Ensure score is within 0-1 range
    relevanceScore = Math.min(1, Math.max(0, relevanceScore));

    // Skip if below minimum relevance threshold
    if (relevanceScore < minRelevanceScore) {
      continue;
    }

    // Get categories for this article
    const categories = articleCategoryMap.get(article.id) || [];

    // Determine author name
    const authorName =
      article.member?.username || article.moderator?.username || "System";

    // Generate recommendation reason
    let recommendationReason =
      "Based on trending discussions in economic and political topics";
    if (categoryIds && categoryIds.length > 0) {
      recommendationReason += " matching your preferred categories";
    }
    if (searchKeywords && searchKeywords.length > 0) {
      recommendationReason += " and search interests";
    }
    if (relevanceScore > 0.7) {
      recommendationReason += " - highly relevant to your interests";
    }

    recommendations.push({
      id: article.id as string & tags.Format<"uuid">,
      title: article.title,
      content:
        article.content.substring(0, 500) +
        (article.content.length > 500 ? "..." : ""),
      authorName,
      categoryCount: categories.length as number &
        tags.Type<"int32"> &
        tags.Minimum<0> &
        tags.Maximum<50>,
      viewCount: article.view_count as number &
        tags.Type<"int32"> &
        tags.Minimum<0> &
        tags.Maximum<1000000>,
      commentCount: (commentCountMap.get(article.id) || 0) as number &
        tags.Type<"int32"> &
        tags.Minimum<0> &
        tags.Maximum<10000>,
      relevanceScore: relevanceScore as number &
        tags.Minimum<0> &
        tags.Maximum<1>,
      recommendationReason,
      categories,
      createdAt: toISOStringSafe(article.created_at),
      updatedAt: toISOStringSafe(article.updated_at),
      version: article.version,
      status: article.status,
    });
  }

  // Sort by relevance score descending and limit results
  recommendations.sort((a, b) => b.relevanceScore - a.relevanceScore);
  const limitedRecommendations = recommendations.slice(0, maxResults);

  // Create pagination metadata using the branded integer type
  const currentPage = 1;
  const totalPages = Math.ceil(recommendations.length / maxResults);
  const limitValue = maxResults;
  const totalRecords = recommendations.length;

  return {
    pagination: {
      current: currentPage.toString() as string & tags.Format<"uuid">,
      pages: totalPages.toString() as string & tags.Format<"uuid">,
      limit: limitValue.toString() as string & tags.Format<"uuid">,
      records: totalRecords.toString() as string & tags.Format<"uuid">,
    },
    data: limitedRecommendations,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
