import { IEconomicDiscussionCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionCategories";
import { ModeratorPayload } from "../decorators/payload/ModeratorPayload";

export async function getEconomicDiscussionModeratorArticlesArticleIdAttachmentsAttachmentId(props: {
  moderator: ModeratorPayload;
  articleId: string & tags.Format<"uuid">;
  attachmentId: string & tags.Format<"uuid">;
}): Promise<IEconomicDiscussionAttachment> {
  // Retrieve the attachment with its associated article
  const attachment =
    await MyGlobal.prisma.economic_discussion_attachments.findUnique({
      where: { id: props.attachmentId },
      include: { article: true },
    });

  if (!attachment) {
    throw new HttpException("Attachment not found", 404);
  }

  // Verify the attachment belongs to the specified article
  if (attachment.economic_discussion_article_id !== props.articleId) {
    throw new HttpException(
      "Attachment does not belong to specified article",
      404,
    );
  }

  // Get article-related data in parallel for efficiency
  const [
    categories,
    attachmentsCount,
    commentsCount,
    memberDetail,
    moderatorDetail,
  ] = await Promise.all([
    // Get categories associated with the article
    MyGlobal.prisma.economic_discussion_article_categories.findMany({
      where: { economic_discussion_article_id: props.articleId },
      include: { category: true },
    }),
    // Count attachments for this article
    MyGlobal.prisma.economic_discussion_attachments.count({
      where: { economic_discussion_article_id: props.articleId },
    }),
    // Count comments for this article
    MyGlobal.prisma.economic_discussion_comments.count({
      where: { economic_discussion_article_id: props.articleId },
    }),
    // Get member author details if applicable
    attachment.article.economic_discussion_member_id
      ? MyGlobal.prisma.economic_discussion_members.findUnique({
          where: { id: attachment.article.economic_discussion_member_id },
        })
      : Promise.resolve(null),
    // Get moderator author details if applicable
    attachment.article.economic_discussion_moderator_id
      ? MyGlobal.prisma.economic_discussion_moderators.findUnique({
          where: { id: attachment.article.economic_discussion_moderator_id },
        })
      : Promise.resolve(null),
  ]);

  // Build the article summary with proper optional field handling
  const articleSummary: IEconomicDiscussionArticle.ISummary = {
    id: attachment.article.id,
    title: attachment.article.title,
    view_count: attachment.article.view_count,
    created_at: toISOStringSafe(attachment.article.created_at),
    updated_at: toISOStringSafe(attachment.article.updated_at),
    economic_discussion_member_id:
      attachment.article.economic_discussion_member_id ??
      typia.random<string & tags.Format<"uuid">>(),
    economic_discussion_moderator_id:
      attachment.article.economic_discussion_moderator_id ??
      typia.random<string & tags.Format<"uuid">>(),
    member_author: memberDetail
      ? {
          id: memberDetail.id,
          username: memberDetail.username,
          email_verified: memberDetail.email_verified,
          reputation_score: memberDetail.reputation_score,
          created_at: toISOStringSafe(memberDetail.created_at),
        }
      : undefined,
    moderator_author: moderatorDetail
      ? {
          id: moderatorDetail.id,
          username: moderatorDetail.username,
          moderation_level: moderatorDetail.moderation_level as
            | "admin"
            | "standard"
            | "senior",
          created_at: toISOStringSafe(moderatorDetail.created_at),
        }
      : undefined,
    categories: categories.map((cat) => ({
      id: cat.category.id,
      code: cat.category.code,
      name: cat.category.name,
      display_order: cat.category.display_order,
      is_active: cat.category.is_active,
      article_count: 0,
    })),
    attachments_count: attachmentsCount,
    comments_count: commentsCount,
    status: attachment.article.status as "pending" | "approved" | "rejected",
  };

  return {
    id: attachment.id,
    article: articleSummary,
    filename: attachment.filename,
    file_size: attachment.file_size,
    file_type: attachment.file_type,
    mime_type: attachment.mime_type,
    uploaded_at: toISOStringSafe(attachment.uploaded_at),
    is_scanned: attachment.is_scanned,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IEconomicDiscussionSearch } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionSearch";
import { IEconomicDiscussionCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionCategory";
import { IPageIEconomicDiscussionSearchQuery } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIEconomicDiscussionSearchQuery";
import { IEconomicDiscussionSearchQuery } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionSearchQuery";
import { IEconomicDiscussionArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionArticle";
import { IEconomicDiscussionMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionMembers";
import { IEconomicDiscussionModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionModerators";
import { IEconomicDiscussionCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionCategories";
import { IEconomicDiscussionSearchMetadata } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionSearchMetadata";
import { IEconomicDiscussionSearchFilters } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionSearchFilters";
import { GuestPayload } from "../decorators/payload/GuestPayload";

export async function patchEconomicDiscussionGuestSearchGlobal(props: {
  guest: GuestPayload;
  body: IEconomicDiscussionSearch.IRequest;
}): Promise<IPageIEconomicDiscussionSearchQuery.ISummary> {
  const {
    query,
    categories,
    scope = "all",
    sort_by = "relevance",
    order = "desc",
    page = 1,
    limit = 20,
  } = props.body;

  const startTime = Date.now();

  const skip = (page - 1) * limit;
  const take = limit;

  const categoryIds = categories?.map((cat) => cat.id) || [];

  const whereCondition: Prisma.economic_discussion_articlesWhereInput = {
    ...(query &&
      query.trim() && {
        OR: [
          {
            title: {
              contains: query satisfies string as string,
              mode: Prisma.QueryMode.insensitive,
            },
          },
          {
            content: {
              contains: query satisfies string as string,
              mode: Prisma.QueryMode.insensitive,
            },
          },
        ],
      }),
    ...(categoryIds.length > 0 && {
      category_id: { in: categoryIds satisfies string[] as string[] },
    }),
    ...((scope === "member" || scope === "all") && {
      OR: [
        { status: "approved" },
        { economic_discussion_member_id: { not: null } },
      ],
    }),
    ...(scope === "moderator" && {}),
    deleted_at: null,
  };

  const [articles, total] = await Promise.all([
    MyGlobal.prisma.economic_discussion_articles.findMany({
      where: whereCondition,
      orderBy: (() => {
        switch (sort_by) {
          case "created_at":
            return { created_at: order };
          case "updated_at":
            return { updated_at: order };
          case "view_count":
            return { view_count: order };
          case "relevance":
          default:
            return [{ title: "asc" }, { created_at: "desc" }];
        }
      })(),
      skip,
      take,
    }),
    MyGlobal.prisma.economic_discussion_articles.count({
      where: whereCondition,
    }),
  ]);

  const searchQueries: IEconomicDiscussionSearchQuery.ISummary[] = articles.map(
    (article) => {
      const memberId = article.economic_discussion_member_id;
      const moderatorId = article.economic_discussion_moderator_id;

      return {
        articles: [
          {
            id: article.id,
            title: article.title,
            view_count: article.view_count,
            created_at: toISOStringSafe(article.created_at),
            updated_at: toISOStringSafe(article.updated_at),
            economic_discussion_member_id: memberId
              ? (memberId satisfies string as string & tags.Format<"uuid">)
              : (null as any),
            economic_discussion_moderator_id: moderatorId
              ? (moderatorId satisfies string as string & tags.Format<"uuid">)
              : (null as any),
            ...(memberId && {
              member_author: {
                id: memberId satisfies string as string & tags.Format<"uuid">,
                username: "unknown",
                email_verified: false,
                reputation_score: 0,
                created_at: toISOStringSafe(new Date()),
              },
            }),
            ...(moderatorId && {
              moderator_author: {
                id: moderatorId satisfies string as string &
                  tags.Format<"uuid">,
                username: "unknown",
                moderation_level: "standard",
                created_at: toISOStringSafe(new Date()),
              },
            }),
            categories: [],
            attachments_count: 0,
            comments_count: 0,
            status: article.status as "pending" | "approved" | "rejected",
          },
        ],
        total_count: 1,
        search_metadata: {
          query: query satisfies string as string,
          filters:
            categoryIds.length > 0
              ? { categories: categoryIds.join(",") }
              : ({} as IEconomicDiscussionSearchFilters),
          sort_order: (() => {
            switch (sort_by) {
              case "created_at":
                return order === "asc" ? "date_asc" : "date_desc";
              case "updated_at":
                return order === "asc" ? "date_asc" : "date_desc";
              case "view_count":
                return "views_desc";
              case "relevance":
              default:
                return "relevance" as const;
            }
          })(),
          execution_time_ms: Date.now() - startTime,
          performed_at: toISOStringSafe(new Date()),
          scope: scope satisfies "member" | "moderator" | "all" as
            | "member"
            | "moderator"
            | "all",
        },
      };
    },
  );

  const totalPages = Math.ceil(total / limit);

  return {
    data: searchQueries,
    pagination: {
      current: page - 1,
      pages: totalPages,
      limit,
      records: total,
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IEconomicDiscussionArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionArticle";
import { ICategoryCode } from "@ORGANIZATION/PROJECT-api/lib/structures/ICategoryCode";
import { IEconomicDiscussionMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionMembers";
import { IEconomicDiscussionModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionModerators";
import { IEconomicDiscussionCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionCategories";
import { MemberPayload } from "../decorators/payload/MemberPayload";

export async function patchEconomicDiscussionMemberArticlesArticleIdCategories(props: {
  member: MemberPayload;
  articleId: string & tags.Format<"uuid">;
  body: IEconomicDiscussionArticle.ICategoriesUpdate;
}): Promise<IEconomicDiscussionArticle.ISummary> {
  // Verify article exists and belongs to the member
  const article = await MyGlobal.prisma.economic_discussion_articles.findUnique(
    {
      where: { id: props.articleId },
    },
  );

  if (!article) {
    throw new HttpException("Article not found", 404);
  }

  if (article.economic_discussion_member_id !== props.member.id) {
    throw new HttpException(
      "You can only update categories for your own articles",
      403,
    );
  }

  // Validate all category codes exist and are active
  if (props.body.category_codes.length > 0) {
    const categories =
      await MyGlobal.prisma.economic_discussion_categories.findMany({
        where: {
          code: { in: props.body.category_codes },
          is_active: true,
        },
        select: { id: true, code: true },
      });

    if (categories.length !== props.body.category_codes.length) {
      throw new HttpException(
        "One or more category codes are invalid or inactive",
        400,
      );
    }
  }

  // Delete existing categories and create new ones in transaction
  const updatedArticle = await MyGlobal.prisma.$transaction(async (tx) => {
    // Delete existing category associations
    await tx.economic_discussion_article_categories.deleteMany({
      where: { economic_discussion_article_id: props.articleId },
    });

    // Create new category associations
    if (props.body.category_codes.length > 0) {
      const categories = await tx.economic_discussion_categories.findMany({
        where: {
          code: { in: props.body.category_codes },
          is_active: true,
        },
      });

      await tx.economic_discussion_article_categories.createMany({
        data: categories.map((category) => ({
          id: v4() as string & tags.Format<"uuid">,
          economic_discussion_article_id: props.articleId,
          economic_discussion_category_id: category.id,
          created_at: new Date(),
        })),
      });
    }

    // Return updated article with categories
    return await tx.economic_discussion_articles.findUnique({
      where: { id: props.articleId },
      include: {
        economic_discussion_article_categories: {
          include: {
            category: true,
          },
        },
      },
    });
  });

  if (!updatedArticle) {
    throw new HttpException("Failed to update article categories", 500);
  }

  // Get member information if available
  let memberAuthor: IEconomicDiscussionMembers.ISummary | undefined;
  if (updatedArticle.economic_discussion_member_id) {
    const member = await MyGlobal.prisma.economic_discussion_members.findUnique(
      {
        where: { id: updatedArticle.economic_discussion_member_id },
      },
    );

    if (member) {
      memberAuthor = {
        id: member.id as string & tags.Format<"uuid">,
        username: member.username,
        email_verified: member.email_verified,
        reputation_score: member.reputation_score as number &
          tags.Type<"int32"> &
          tags.Minimum<0>,
        created_at: toISOStringSafe(member.created_at),
      };
    }
  }

  // Get moderator information if available
  let moderatorAuthor: IEconomicDiscussionModerators.ISummary | undefined;
  if (updatedArticle.economic_discussion_moderator_id) {
    const moderator =
      await MyGlobal.prisma.economic_discussion_moderators.findUnique({
        where: { id: updatedArticle.economic_discussion_moderator_id },
      });

    if (moderator) {
      moderatorAuthor = {
        id: moderator.id as string & tags.Format<"uuid">,
        username: moderator.username,
        moderation_level: moderator.moderation_level as
          | "standard"
          | "senior"
          | "admin",
        created_at: toISOStringSafe(moderator.created_at),
      };
    }
  }

  const categories: IEconomicDiscussionCategories.ISummary[] =
    updatedArticle.economic_discussion_article_categories.map(
      (articleCategory) => ({
        id: articleCategory.category.id as string & tags.Format<"uuid">,
        code: articleCategory.category.code,
        name: articleCategory.category.name,
        display_order: articleCategory.category.display_order as number &
          tags.Type<"int32">,
        is_active: articleCategory.category.is_active,
        article_count: articleCategory.category.article_count as number &
          tags.Type<"int32"> &
          tags.Minimum<0>,
      }),
    );

  return {
    id: updatedArticle.id,
    title: updatedArticle.title,
    view_count: updatedArticle.view_count as number &
      tags.Type<"int32"> &
      tags.Minimum<0>,
    created_at: toISOStringSafe(updatedArticle.created_at),
    updated_at: toISOStringSafe(updatedArticle.updated_at),
    economic_discussion_member_id:
      updatedArticle.economic_discussion_member_id as string &
        tags.Format<"uuid">,
    economic_discussion_moderator_id:
      updatedArticle.economic_discussion_moderator_id as string &
        tags.Format<"uuid">,
    member_author: memberAuthor,
    moderator_author: moderatorAuthor,
    categories,
    attachments_count: 0,
    comments_count: 0,
    status: updatedArticle.status as "pending" | "approved" | "rejected",
  };
}

