import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IEconomicDiscussionAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionAttachment";
import { IEconomicDiscussionArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionArticle";
import { IEconomicDiscussionMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionMembers";
import { IEconomicDiscussionModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionModerators";
import { IEconomicDiscussionCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionCategories";
import { MemberPayload } from "../decorators/payload/MemberPayload";

export async function putEconomicDiscussionMemberArticlesArticleIdAttachmentsAttachmentId(props: {
  member: MemberPayload;
  articleId: string & tags.Format<"uuid">;
  attachmentId: string & tags.Format<"uuid">;
  body: IEconomicDiscussionAttachment.IUpdate;
}): Promise<IEconomicDiscussionAttachment> {
  // Find the attachment and verify it exists
  const attachment =
    await MyGlobal.prisma.economic_discussion_attachments.findUnique({
      where: { id: props.attachmentId },
    });

  if (!attachment) {
    throw new HttpException("Attachment not found", 404);
  }

  // Verify the attachment belongs to the specified article
  if (attachment.economic_discussion_article_id !== props.articleId) {
    throw new HttpException(
      "Attachment does not belong to the specified article",
      404,
    );
  }

  // Find the article and verify member ownership in a single query
  const article = await MyGlobal.prisma.economic_discussion_articles.findUnique(
    {
      where: {
        id: props.articleId,
      },
      include: {
        member: true,
        moderator: true,
      },
    },
  );

  if (!article) {
    throw new HttpException("Article not found", 404);
  }

  // Verify the member owns this article
  if (
    !article.economic_discussion_member_id ||
    article.economic_discussion_member_id !== props.member.id
  ) {
    throw new HttpException(
      "You do not have permission to update attachments for this article",
      403,
    );
  }

  // Get categories for the article
  const articleCategories =
    await MyGlobal.prisma.economic_discussion_article_categories.findMany({
      where: { economic_discussion_article_id: props.articleId },
      include: {
        category: true,
      },
    });

  // Get attachment count for the article
  const attachmentsCount =
    await MyGlobal.prisma.economic_discussion_attachments.count({
      where: { economic_discussion_article_id: props.articleId },
    });

  // Get comment count for the article
  const commentsCount =
    await MyGlobal.prisma.economic_discussion_comments.count({
      where: { economic_discussion_article_id: props.articleId },
    });

  // Update the attachment with the new filename
  const updatedAttachment =
    await MyGlobal.prisma.economic_discussion_attachments.update({
      where: { id: props.attachmentId },
      data: {
        filename: props.body.filename,
      },
    });

  // Build the article summary for the response
  const articleSummary: IEconomicDiscussionArticle.ISummary = {
    id: article.id,
    title: article.title,
    view_count: article.view_count,
    created_at: toISOStringSafe(article.created_at),
    updated_at: toISOStringSafe(article.updated_at),
    economic_discussion_member_id: article.economic_discussion_member_id,
    economic_discussion_moderator_id:
      article.economic_discussion_moderator_id !== null
        ? typia.assert<string & tags.Format<"uuid">>(
            article.economic_discussion_moderator_id,
          )
        : typia.assert<string & tags.Format<"uuid">>(
            "00000000-0000-0000-0000-000000000000",
          ),
    member_author: article.member
      ? {
          id: article.member.id,
          username: article.member.username,
          email_verified: article.member.email_verified,
          reputation_score: article.member.reputation_score,
          created_at: toISOStringSafe(article.member.created_at),
        }
      : undefined,
    moderator_author: undefined, // Member articles won't have moderator author
    categories: articleCategories.map((ac) => ({
      id: ac.category.id,
      name: ac.category.name,
      code: ac.category.code,
      is_active: ac.category.is_active,
      display_order: ac.category.display_order,
      article_count: 0, // Would need separate query, but interface requires it
    })),
    attachments_count: attachmentsCount,
    comments_count: commentsCount,
    status: article.status as "pending" | "approved" | "rejected",
  };

  // Return the updated attachment
  return {
    id: updatedAttachment.id,
    article: articleSummary,
    filename: updatedAttachment.filename,
    file_size: updatedAttachment.file_size,
    file_type: updatedAttachment.file_type,
    mime_type: updatedAttachment.mime_type,
    uploaded_at: toISOStringSafe(updatedAttachment.uploaded_at),
    is_scanned: updatedAttachment.is_scanned,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IEconomicDiscussionAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionAttachment";
import { IEconomicDiscussionArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionArticle";
import { IEconomicDiscussionMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionMembers";
import { IEconomicDiscussionModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionModerators";
import { IEconomicDiscussionCategories } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionCategories";
import { ModeratorPayload } from "../decorators/payload/ModeratorPayload";

export async function putEconomicDiscussionModeratorArticlesArticleIdAttachmentsAttachmentId(props: {
  moderator: ModeratorPayload;
  articleId: string & tags.Format<"uuid">;
  attachmentId: string & tags.Format<"uuid">;
  body: IEconomicDiscussionAttachment.IUpdate;
}): Promise<IEconomicDiscussionAttachment> {
  // Verify attachment exists and belongs to the specified article
  const existing =
    await MyGlobal.prisma.economic_discussion_attachments.findFirst({
      where: {
        id: props.attachmentId,
        economic_discussion_article_id: props.articleId,
      },
    });

  if (!existing) {
    throw new HttpException(
      "Attachment not found or does not belong to this article",
      404,
    );
  }

  // Check if another attachment on the same article already has the new filename
  const filenameConflict =
    await MyGlobal.prisma.economic_discussion_attachments.findFirst({
      where: {
        economic_discussion_article_id: props.articleId,
        filename: props.body.filename,
        NOT: { id: props.attachmentId },
      },
    });

  if (filenameConflict) {
    throw new HttpException(
      "An attachment with this filename already exists on this article",
      409,
    );
  }

  // Update the attachment with new filename
  const updated = await MyGlobal.prisma.economic_discussion_attachments.update({
    where: {
      id: props.attachmentId,
    },
    data: {
      filename: props.body.filename,
    },
  });

  // Get the article details separately
  const article = await MyGlobal.prisma.economic_discussion_articles.findUnique(
    {
      where: { id: props.articleId },
    },
  );

  if (!article) {
    throw new HttpException("Article not found", 404);
  }

  return {
    id: updated.id,
    article: {
      id: article.id,
      title: article.title,
      view_count: article.view_count,
      created_at: toISOStringSafe(article.created_at),
      updated_at: toISOStringSafe(article.updated_at),
      economic_discussion_member_id:
        article.economic_discussion_member_id !== null &&
        article.economic_discussion_member_id !== undefined
          ? (article.economic_discussion_member_id satisfies string as string)
          : typia.random<string & tags.Format<"uuid">>(),
      economic_discussion_moderator_id:
        article.economic_discussion_moderator_id !== null &&
        article.economic_discussion_moderator_id !== undefined
          ? (article.economic_discussion_moderator_id satisfies string as string)
          : typia.random<string & tags.Format<"uuid">>(),
      member_author: undefined, // Would need separate query to populate
      moderator_author: undefined, // Would need separate query to populate
      categories: [], // Would need separate query to populate
      attachments_count: 0, // Default value for cached count
      comments_count: 0, // Default value for cached count
      status: article.status as "pending" | "approved" | "rejected",
    },
    filename: updated.filename,
    file_size: updated.file_size,
    file_type: updated.file_type,
    mime_type: updated.mime_type,
    uploaded_at: toISOStringSafe(updated.uploaded_at),
    is_scanned: updated.is_scanned,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IEconomicDiscussionGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionGuest";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthGuestJoin(props: {
  body: IEconomicDiscussionGuest.ICreate;
}): Promise<IEconomicDiscussionGuest.IAuthorized> {
  // Get current timestamp as ISO string
  const now = toISOStringSafe(new Date());
  const accessExpires = toISOStringSafe(new Date(Date.now() + 60 * 60 * 1000)); // 1 hour
  const refreshExpires = toISOStringSafe(
    new Date(Date.now() + 24 * 60 * 60 * 1000),
  ); // 24 hours
  const sessionExpires = toISOStringSafe(
    new Date(Date.now() + 24 * 60 * 60 * 1000),
  ); // 24 hours

  // Extract IP from execution context - NestJS provides this through the request
  // For guest operations, we use a default IP since this is a public endpoint
  const ip = "127.0.0.1"; // This would be extracted from request context in production

  // Check for existing guest with same IP and user_agent combination
  const existingGuest =
    await MyGlobal.prisma.economic_discussion_guests.findFirst({
      where: {
        ip_address: ip,
        user_agent: props.body.user_agent ?? null,
      },
    });

  let guestId: string & tags.Format<"uuid">;
  let guestUsername: string;
  let guestCreatedAt: string & tags.Format<"date-time">;
  let guestLastActivityAt: string & tags.Format<"date-time">;
  let articlesCount: number;
  let downloadsCount: number;

  if (existingGuest) {
    // Update existing guest activity
    const updatedGuest =
      await MyGlobal.prisma.economic_discussion_guests.update({
        where: { id: existingGuest.id },
        data: {
          last_activity_at: now,
        },
      });

    guestId = updatedGuest.id;
    guestUsername = updatedGuest.username;
    guestCreatedAt = toISOStringSafe(updatedGuest.created_at);
    guestLastActivityAt = toISOStringSafe(updatedGuest.last_activity_at);
    articlesCount = updatedGuest.articles_viewed_count;
    downloadsCount = updatedGuest.downloads_count;
  } else {
    // Create new guest account
    guestId = v4() as string & tags.Format<"uuid">;

    const guest = await MyGlobal.prisma.economic_discussion_guests.create({
      data: {
        id: guestId,
        username: props.body.username,
        ip_address: ip,
        user_agent: props.body.user_agent ?? null,
        created_at: now,
        last_activity_at: now,
        articles_viewed_count: 0,
        downloads_count: 0,
      },
    });

    guestUsername = guest.username;
    guestCreatedAt = guestCreatedAt = toISOStringSafe(guest.created_at);
    guestLastActivityAt = toISOStringSafe(guest.last_activity_at);
    articlesCount = guest.articles_viewed_count;
    downloadsCount = guest.downloads_count;
  }

  // Create guest session
  const sessionId = v4() as string & tags.Format<"uuid">;
  const session =
    await MyGlobal.prisma.economic_discussion_guest_sessions.create({
      data: {
        id: sessionId,
        economic_discussion_guest_id: guestId,
        ip: ip,
        href: "", // Would be extracted from request context
        referrer: null,
        created_at: now,
        expired_at: sessionExpires,
      },
    });

  // Generate JWT tokens
  const token: IAuthorizationToken = {
    access: jwt.sign(
      {
        type: "guest",
        id: guestId,
        session_id: sessionId,
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "guest",
        id: guestId,
        session_id: sessionId,
        tokenType: "refresh",
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "24h",
        issuer: "autobe",
      },
    ),
    expired_at: accessExpires,
    refreshable_until: refreshExpires,
  };

  return {
    id: guestId,
    username: guestUsername,
    created_at: guestCreatedAt,
    last_activity_at: guestLastActivityAt,
    articles_viewed_count: articlesCount,
    downloads_count: downloadsCount,
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IEconomicDiscussionGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionGuest";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthGuestRefresh(props: {
  body: IEconomicDiscussionGuest.IRefresh;
}): Promise<IEconomicDiscussionGuest.IAuthorized> {
  // Find the guest by ID
  const guest = await MyGlobal.prisma.economic_discussion_guests.findUnique({
    where: { id: props.body.id },
  });

  if (!guest) {
    throw new HttpException("Guest session not found", 404);
  }

  // Generate new tokens with same session_id
  const accessExpires: Date = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires: Date = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
  const currentTime: Date = new Date();

  const accessToken: string = jwt.sign(
    {
      id: guest.id,
      session_id: guest.id,
      type: "guest",
      created_at: toISOStringSafe(currentTime),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );

  const refreshToken: string = jwt.sign(
    {
      id: guest.id,
      session_id: guest.id,
      type: "guest",
      tokenType: "refresh",
      created_at: toISOStringSafe(currentTime),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  // Update guest last activity
  await MyGlobal.prisma.economic_discussion_guests.update({
    where: { id: guest.id },
    data: {
      last_activity_at: currentTime,
    },
  });

  return {
    id: guest.id,
    username: guest.username,
    created_at: toISOStringSafe(guest.created_at),
    last_activity_at: toISOStringSafe(currentTime),
    articles_viewed_count: guest.articles_viewed_count,
    downloads_count: guest.downloads_count,
    token: {
      access: accessToken,
      refresh: refreshToken,
      expired_at: toISOStringSafe(accessExpires),
      refreshable_until: toISOStringSafe(refreshExpires),
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IEconomicDiscussionMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionMember";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthMemberJoin(props: {
  body: IEconomicDiscussionMember.ICreate;
}): Promise<IEconomicDiscussionMember.IAuthorized> {
  // Check for existing username
  const existingUsername =
    await MyGlobal.prisma.economic_discussion_members.findFirst({
      where: { username: props.body.username },
    });
  if (existingUsername) {
    throw new HttpException("Username already taken", 409);
  }

  // Check for existing email
  const existingEmail =
    await MyGlobal.prisma.economic_discussion_members.findFirst({
      where: { email: props.body.email },
    });
  if (existingEmail) {
    throw new HttpException("Email already registered", 409);
  }

  // Hash password
  const hashedPassword = await PasswordUtil.hash(props.body.password);

  // Create member record
  const member = await MyGlobal.prisma.economic_discussion_members.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      username: props.body.username,
      email: props.body.email,
      password_hash: hashedPassword,
      email_verified: props.body.email_verified ?? false,
      reputation_score: 0,
      created_at: toISOStringSafe(new Date()),
      updated_at: toISOStringSafe(new Date()),
    },
  });

  // Create session
  const accessExpires = toISOStringSafe(new Date(Date.now() + 60 * 60 * 1000));
  const refreshExpires = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );
  const session =
    await MyGlobal.prisma.economic_discussion_member_sessions.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        economic_discussion_member_id: member.id,
        ip: "0.0.0.0", // Populated by middleware in production
        href: "/auth/member/join",
        referrer: null,
        created_at: toISOStringSafe(new Date()),
        expired_at: accessExpires,
      },
    });

  // Generate JWT tokens
  const token: IAuthorizationToken = {
    access: jwt.sign(
      {
        type: "member",
        id: member.id,
        session_id: session.id,
        created_at: toISOStringSafe(new Date()),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "member",
        id: member.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: toISOStringSafe(new Date()),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: accessExpires,
    refreshable_until: refreshExpires,
  };

  return {
    member: {
      id: member.id,
      username: member.username,
      email: member.email,
    },
    access_token: token.access,
    refresh_token: token.refresh,
    expires_in: 3600 as number & tags.Type<"int32">,
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IEconomicDiscussionMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionMember";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthMemberRefresh(props: {
  body: IEconomicDiscussionMember.IRefresh;
}): Promise<IEconomicDiscussionMember.IAuthorized> {
  // Verify and decode refresh token
  let decoded: {
    id: string & tags.Format<"uuid">;
    session_id: string & tags.Format<"uuid">;
    type: "member";
  };

  try {
    decoded = jwt.verify(
      props.body.refresh_token,
      MyGlobal.env.JWT_SECRET_KEY,
      { issuer: "autobe" },
    ) as {
      id: string & tags.Format<"uuid">;
      session_id: string & tags.Format<"uuid">;
      type: "member";
    };
  } catch (error) {
    throw new HttpException("Invalid or expired refresh token", 401);
  }

  // Validate token type
  if (decoded.type !== "member") {
    throw new HttpException("Invalid token type", 403);
  }

  // Validate session exists and is active
  const session =
    await MyGlobal.prisma.economic_discussion_member_sessions.findFirst({
      where: {
        id: decoded.session_id,
        economic_discussion_member_id: decoded.id,
      },
      include: {
        member: true,
      },
    });

  if (!session) {
    throw new HttpException("Session expired or revoked", 401);
  }

  // Generate token expiration times as ISO strings
  const now = Date.now();
  const accessExpires = now + 30 * 60 * 1000; // 30 minutes
  const refreshExpires = now + 7 * 24 * 60 * 60 * 1000; // 7 days

  // Generate new tokens with same session_id
  const accessToken = jwt.sign(
    {
      type: decoded.type,
      id: decoded.id,
      session_id: decoded.session_id,
      created_at: toISOStringSafe(new Date()),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "30m",
      issuer: "autobe",
    },
  );

  const refreshToken = jwt.sign(
    {
      type: decoded.type,
      id: decoded.id,
      session_id: decoded.session_id,
      tokenType: "refresh",
      created_at: toISOStringSafe(new Date()),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  // Update session expiration
  await MyGlobal.prisma.economic_discussion_member_sessions.update({
    where: { id: decoded.session_id },
    data: { expired_at: new Date(refreshExpires) },
  });

  return {
    member: {
      id: session.member.id,
      username: session.member.username,
      email: session.member.email,
    },
    access_token: accessToken,
    refresh_token: refreshToken,
    expires_in: 1800, // 30 minutes in seconds
    token: {
      access: accessToken,
      refresh: refreshToken,
      expired_at: toISOStringSafe(new Date(accessExpires)),
      refreshable_until: toISOStringSafe(new Date(refreshExpires)),
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IEconomicDiscussionModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionModerator";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthModeratorJoin(props: {
  body: IEconomicDiscussionModerator.ICreate;
}): Promise<IEconomicDiscussionModerator.IAuthorized> {
  // Check for duplicate username
  const existingUsername =
    await MyGlobal.prisma.economic_discussion_moderators.findUnique({
      where: { username: props.body.username },
    });

  if (existingUsername) {
    throw new HttpException("Username already exists", 409);
  }

  // Check for duplicate email
  const existingEmail =
    await MyGlobal.prisma.economic_discussion_moderators.findUnique({
      where: { email: props.body.email },
    });

  if (existingEmail) {
    throw new HttpException("Email already exists", 409);
  }

  // Hash password
  const hashedPassword = await PasswordUtil.hash(props.body.password_hash);

  // Create moderator record
  const moderator = await MyGlobal.prisma.economic_discussion_moderators.create(
    {
      data: {
        id: v4() as string & tags.Format<"uuid">,
        username: props.body.username,
        email: props.body.email,
        password_hash: hashedPassword,
        email_verified: props.body.email_verified ?? false,
        two_factor_enabled: props.body.two_factor_enabled ?? false,
        moderation_level: props.body.moderation_level,
        created_at: toISOStringSafe(new Date()),
        updated_at: toISOStringSafe(new Date()),
      },
    },
  );

  // Create session
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);

  const session =
    await MyGlobal.prisma.economic_discussion_moderator_sessions.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        economic_discussion_moderator_id: moderator.id,
        ip: "0.0.0.0", // Server-side default since no IP in props
        href: "/auth/moderator/join",
        referrer: null,
        created_at: toISOStringSafe(new Date()),
        expired_at: toISOStringSafe(accessExpires),
      },
    });

  // Generate JWT tokens
  const token: IAuthorizationToken = {
    access: jwt.sign(
      {
        type: "moderator",
        id: moderator.id,
        session_id: session.id,
        created_at: toISOStringSafe(new Date()),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "moderator",
        id: moderator.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: toISOStringSafe(new Date()),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };

  // Return moderator data
  return {
    id: moderator.id,
    username: moderator.username,
    email: moderator.email,
    email_verified: moderator.email_verified,
    two_factor_enabled: moderator.two_factor_enabled,
    moderation_level: moderator.moderation_level,
    created_at: toISOStringSafe(moderator.created_at),
    updated_at: toISOStringSafe(moderator.updated_at),
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IEconomicDiscussionModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IEconomicDiscussionModerator";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthModeratorRefresh(props: {
  body: IEconomicDiscussionModerator.IRefresh;
}): Promise<IEconomicDiscussionModerator.IAuthorized> {
  // Step 1: Decode and verify refresh token
  let decoded: {
    id: string;
    session_id: string;
    type: "moderator";
  };
  try {
    decoded = jwt.verify(
      props.body.refresh_token,
      MyGlobal.env.JWT_SECRET_KEY,
      { issuer: "autobe" },
    ) as {
      id: string;
      session_id: string;
      type: "moderator";
    };
  } catch (error) {
    throw new HttpException("Invalid or expired refresh token", 401);
  }

  // Step 2: Validate token type matches expected actor
  if (decoded.type !== "moderator") {
    throw new HttpException("Invalid token type", 403);
  }

  // Step 3: Validate session exists and is active
  const session =
    await MyGlobal.prisma.economic_discussion_moderator_sessions.findFirst({
      where: {
        id: decoded.session_id,
        economic_discussion_moderator_id: decoded.id,
      },
      include: {
        moderator: true,
      },
    });

  if (!session) {
    throw new HttpException("Session expired or revoked", 401);
  }

  // Step 4: Check moderator account status
  if (!session.moderator) {
    throw new HttpException("Moderator account not found", 404);
  }

  // Step 5: Generate new tokens with same session_id for continuity
  const now = new Date().toISOString();
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000).toISOString();
  const refreshExpires = new Date(
    Date.now() + 7 * 24 * 60 * 60 * 1000,
  ).toISOString();

  const accessToken = jwt.sign(
    {
      type: "moderator",
      id: decoded.id,
      session_id: decoded.session_id, // Reuse same session for continuity
      created_at: now,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );

  const refreshToken = jwt.sign(
    {
      type: "moderator",
      id: decoded.id,
      session_id: decoded.session_id, // Reuse same session for continuity
      tokenType: "refresh",
      created_at: now,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  // Step 6: Update session expiration
  await MyGlobal.prisma.economic_discussion_moderator_sessions.update({
    where: {
      id: decoded.session_id,
    },
    data: {
      expired_at: refreshExpires,
    },
  });

  // Step 7: Return complete moderator profile with new tokens
  const moderator = session.moderator;
  return {
    id: moderator.id as string & tags.Format<"uuid">,
    username: moderator.username,
    email: moderator.email as string & tags.Format<"email">,
    email_verified: moderator.email_verified,
    two_factor_enabled: moderator.two_factor_enabled,
    moderation_level: moderator.moderation_level,
    created_at: toISOStringSafe(moderator.created_at),
    updated_at: toISOStringSafe(moderator.updated_at),
    token: {
      access: accessToken,
      refresh: refreshToken,
      expired_at: accessExpires as string & tags.Format<"date-time">,
      refreshable_until: refreshExpires as string & tags.Format<"date-time">,
    },
  };
}

