    @Ip()
    ip: string,
    @TypedBody()
    body: IEconomicDiscussionModerator.ILogin,
  ): Promise<IEconomicDiscussionModerator.IAuthorized> {
    try {
      return await postAuthModeratorLogin({
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Refresh moderator access tokens.
   *
   * Extends moderator sessions by exchanging refresh tokens for new access
   * tokens without requiring repeated credential entry.
   *
   * The refresh operation validates existing refresh tokens issued during
   * initial login or previous refresh cycles, generating fresh access tokens
   * with updated expiration timestamps. This maintains continuous
   * authentication state for administrative sessions.
   *
   * Token refresh preserves authorization context including moderator role
