    @TypedParam("attachmentId")
    attachmentId: string,
  ): Promise<void> {
    try {
      return await deleteEconomicDiscussionMemberArticlesArticleIdAttachmentsAttachmentId(
        {
          member,
          articleId,
          attachmentId,
        },
      );
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
